 "換氣":"ventilation","肺泡":"alveoli","第一型肺泡細胞":"alvcell","第二型肺泡細胞":"alvcell","傳導區":"condzone","呼吸區":"condzone","黏液纖毛電扶梯":"mucocil",
 "胸膜":"pleura","胸膜腔":"pleura","氣胸":"pneumothorax","波以耳定律":"boyle","肺內壓":"intrapulm","胸膜內壓":"intrapulm","順應性":"compliance",
 "表面張力":"surfacetension","拉普拉斯定律":"surfacetension","表面活性劑":"surfactant","呼吸窘迫症候群":"rds","橫膈":"diaphragm","膈神經":"diaphragm",
 "外肋間肌":"intercostal","內肋間肌":"intercostal","潮氣容積":"tidal","肺活量":"vc","殘氣容積":"rv","功能肋餘容量":"frc","吸氣儲備容積":"lungvol","呼氣儲備容積":"lungvol","總肺容量":"lungvol",
 "死腔":"deadspace","解剖死腔":"deadspace","FEV₁":"fev1","氣喘":"asthma","肺氣腫":"emphysema","COPD":"copd","慢性阻塞性肺病":"copd","肺纖維化":"fibrosis",
