"鈣":"calcium","鈣質":"calcium","磷":"phosphorus","磷酸鹽":"phosphorus","鎂":"magnesium","鈉":"sodium","鉀":"potassium","氯":"chloride",
"鐵":"iron","鐵質":"iron","鋅":"zinc","銅":"copper","碘":"iodine","硒":"selenium","氟":"fluoride","錳":"manganese","鉻":"chromium","鉬":"molybdenum",
