Object.assign(GL,{"pregang":{"t":"節前、節後神經元 preganglionic / postganglionic","d":"自主神經從中樞到器官要經過兩個神經元接力：前一棒叫節前神經元，後一棒叫節後神經元。","c":"9.1","f":"節前神經元的細胞本體在腦幹或脊髓，軸突有髓鞘，釋放 ACh；節後神經元的本體在自主神經節，軸突無髓鞘，伸到器官，釋放 ACh（副交感）或正腎上腺素（多數交感）。","m":"<b>體神經一條到底；自主神經兩段接力</b>。"},
"autogang":{"t":"自主神經節 autonomic ganglion","d":"自主神經的「轉運站」，節前神經元在這裡把訊號交給節後神經元。","c":"9.1","f":"交感、副交感的神經節都使用 <b>ACh＋菸鹼型受體</b>（N<sub>N</sub>），所以阻斷神經節的藥物會同時影響兩者。","m":"<b>所有自主神經節：ACh、菸鹼型</b>。"},
"symp":{"t":"交感神經 sympathetic division","d":"自主神經中負責緊急動員的一支：「戰或逃」。","c":"9.2","w":"節前神經元在脊髓胸腰段（T1–L2）的側角；神經節在脊柱兩旁的交感神經鏈或腹腔的側支神經節。","f":"節前短、節後長；節後大多釋放<b>正腎上腺素</b>作用在 α、β 受體（汗腺例外用 ACh）。也直接刺激腎上腺髓質分泌腎上腺素。","m":"<b>交感：胸腰、節前短節後長、正腎上腺素</b>。"},
"parasymp":{"t":"副交感神經 parasympathetic division","d":"自主神經中負責休息、消化與儲存的一支。","c":"9.2","w":"節前神經元在腦幹（第 III、VII、IX、X 對腦神經）與脊髓薦段（S2–S4）；神經節在器官旁或器官壁內（終末神經節）。","f":"節前長、節後短；節後釋放 <b>ACh</b> 作用在毒蕈鹼型受體：心跳變慢、瞳孔縮小、促進唾液與消化液分泌、腸胃蠕動、排尿與排便。","e":"迷走神經（X）占了副交感纖維的大部分。","m":"<b>副交感：顱薦、節前長節後短、ACh</b>。"},
"schain":{"t":"交感神經鏈 sympathetic chain","d":"脊柱兩側上下相連的椎旁神經節，讓交感訊號能在不同節段間擴散。","c":"9.2","w":"脊柱兩側，從頸部延伸到薦部，像兩串珠鍊。","f":"節前纖維進入交感鏈後可以在同一節、上下其他節換神經元，或穿過去到腹部的側支神經節；所以一條節前纖維能影響很多節後神經元。","m":"<b>交感鏈＝縱向的轉運鍊</b>。"},
"termgang":{"t":"終末神經節 terminal ganglia","d":"副交感神經在器官旁邊或器官壁裡的神經節。","c":"9.2","f":"因為神經節靠近器官，節後纖維很短、作用範圍集中，所以副交感的反應比較局部、精準。","m":"<b>副交感把轉運站開在器官門口</b>。"},
"massact":{"t":"大量放電 mass activation","d":"緊急時，交感神經會「全面啟動」，全身各器官同時進入戰鬥模式。","c":"9.2","f":"一條節前纖維可和約 20 個以上的節後神經元形成突觸（發散），加上腎上腺髓質把腎上腺素送進血液，作用遍及全身。副交感則較常分別作用於個別器官。","m":"<b>交感一發全身動、副交感各自處理</b>。"},
"admed":{"t":"腎上腺髓質 adrenal medulla","d":"腎上腺的內層，本質是特化的交感節後神經元，受刺激時分泌腎上腺素（約 80%）與正腎上腺素到血液。","c":"9.2；第 11 章","w":"腎上腺的中心部分（外層是分泌類固醇的皮質）。","f":"由神經嵴而來，相當於沒有軸突的交感節後神經元：直接受交感節前纖維（ACh、菸鹼型）支配，把<b>腎上腺素</b>（約 80%）與正腎上腺素分泌到血液。皮質醇幫助髓質把正腎上腺素轉成腎上腺素。","e":"嗜鉻細胞瘤：髓質腫瘤分泌大量兒茶酚胺 → 陣發性高血壓、頭痛、心悸、冒汗。","m":"<b>髓質＝交感神經的分泌版</b>。"},
"fightflight":{"t":"戰或逃 fight or flight","d":"交感神經主導的緊急反應：心跳加快、血壓升高、瞳孔放大、支氣管擴張、血糖上升、消化變慢。","c":"9.2","f":"心跳與收縮力↑、血壓↑、血液轉向骨骼肌與心臟（皮膚、腸胃血流↓）、支氣管擴張、瞳孔放大、肝醣分解與脂肪分解（血糖、游離脂肪酸↑）、流汗、腸胃蠕動與消化液分泌↓。","e":"考試前緊張時口乾、心跳快、胃口差，就是交感神經的作用。","m":"<b>心快、肺開、眼大、糖升、腸停</b>。"},
"restdigest":{"t":"休息與消化 rest and digest","d":"副交感神經主導的狀態：心跳變慢、消化液分泌與腸胃蠕動增加、儲存能量。","c":"9.2","f":"心跳變慢、瞳孔縮小、支氣管收縮、唾液與胃液胰液分泌、腸胃蠕動、膽囊收縮、排尿排便，並促進能量儲存（胰島素分泌）。","m":"<b>SLUDD</b>：流涎、流淚、排尿、消化、排便——副交感的作用。"},
"cholin":{"t":"膽鹼性、腎上腺素性 cholinergic / adrenergic","d":"<b>膽鹼性</b>：釋放乙醯膽鹼的神經元（所有節前、副交感節後、交感到汗腺）。<b>腎上腺素性</b>：釋放正腎上腺素（多數交感節後）。","c":"9.3","f":"<b>膽鹼性</b>神經元釋放 ACh：所有自主神經節前神經元、副交感節後神經元、交感到汗腺的節後神經元、體運動神經元。<b>腎上腺素性</b>神經元釋放正腎上腺素：大部分交感節後神經元。","m":"<b>交感節後用 NE（汗腺除外），其他通通 ACh</b>。"},
"adrrec":{"t":"腎上腺素性受體 adrenergic receptors","d":"能接收正腎上腺素與腎上腺素的受體，分成 α、β 兩大類與多個次型，決定器官會收縮還是放鬆。","c":"9.3；第 11、14 章","f":"都是 G 蛋白偶聯受體：α₁ → IP₃、Ca²⁺↑（收縮）；α₂ → cAMP↓（抑制）；β₁、β₂、β₃ → cAMP↑。不同器官擁有的受體不同，所以同一個激素在不同器官作用不同。","m":"<b>α 多收縮、β 多放鬆（心臟例外：β₁ 興奮）</b>。"},
"alpha1":{"t":"α1 受體","d":"讓血管收縮、血壓上升的腎上腺素受體。","c":"9.3","w":"皮膚、腸胃、腎臟的血管平滑肌；瞳孔放射肌；膀胱與腸胃的括約肌。","e":"α₁ 阻斷劑用來降血壓與改善攝護腺肥大的排尿困難；鼻塞藥（α 致效劑）使鼻黏膜血管收縮。","m":"<b>α₁＝血管收縮</b>。"},
"alpha2":{"t":"α2 受體","d":"負責「踩煞車」的腎上腺素受體，減少正腎上腺素與胰島素的釋放。","c":"9.3","f":"位於交感神經末梢的突觸前膜，正腎上腺素釋放太多時回頭抑制自己（負回饋）；在胰島 β 細胞上抑制胰島素分泌（緊急時保住血糖）。","e":"α₂ 致效劑（clonidine）降低交感輸出而降血壓。","m":"<b>α₂＝自我煞車</b>。"},
"beta1":{"t":"β1 受體","d":"主要在心臟：心跳加快、收縮力增強；也在腎臟促進腎素分泌。","c":"9.3；第 14 章","w":"心臟（節律點、心肌）、腎臟近腎絲球細胞。","f":"經 cAMP 使心跳加快、收縮力增強、傳導加快；促進腎素釋放 → 血管收縮素 → 血壓上升。","m":"<b>β₁＝1 個心臟</b>。"},
"beta2":{"t":"β2 受體","d":"支氣管平滑肌放鬆（擴張）、骨骼肌與冠狀血管擴張、子宮放鬆、肝醣分解。","e":"氣喘吸入劑 albuterol 是 β2 致效劑。","c":"9.3；第 16 章","w":"支氣管平滑肌、骨骼肌與冠狀動脈的血管、子宮、肝臟、胰島。","f":"經 cAMP 使平滑肌放鬆；在肝臟促進肝醣分解與糖質新生。","m":"<b>β₂＝2 片肺</b>：支氣管擴張。"},
"beta3":{"t":"β3 受體","d":"位於脂肪細胞與膀胱的腎上腺素受體，促進脂肪分解。","c":"9.3","f":"活化激素敏感性脂解酶 → 釋放游離脂肪酸；在棕色脂肪促進產熱。也使膀胱逼尿肌放鬆（β₃ 致效劑可治療膀胱過動症）。","m":"<b>β₃＝燒脂肪</b>。"},
"betablock":{"t":"β 阻斷劑 β-blockers","d":"阻斷 β 受體的藥：降低心跳與血壓。非選擇性者同時阻斷 β2，可能引起支氣管收縮。","c":"9.3；第 14 章","f":"阻斷 β₁ → 心跳變慢、收縮力降低、腎素減少 → 血壓下降、心臟耗氧減少。選擇性 β₁ 阻斷劑對肺影響較小。","e":"用於高血壓、心絞痛、心律不整、心衰竭；氣喘病人避免非選擇性藥物。也可能掩蓋低血糖時的心悸、顫抖症狀，糖尿病人要注意。","m":"<b>藥名多以 -olol 結尾</b>（propranolol、atenolol）。"},
"agonist":{"t":"致效劑、拮抗劑 agonist / antagonist","d":"致效劑是「假鑰匙能開門」，拮抗劑是「假鑰匙插進去卡住門」。","c":"9.3","f":"致效劑結合受體並產生和天然物質一樣的反應；拮抗劑結合受體但不活化，還擋住天然物質，屬於阻斷劑。","e":"沙丁胺醇（β₂ 致效劑）治療氣喘；阿托平（毒蕈鹼型拮抗劑）、β 阻斷劑。","m":"<b>致效＝模仿、拮抗＝擋住</b>。"},
"nanc":{"t":"非腎上腺素非膽鹼性 NANC","d":"既不用 ACh 也不用 NE 的自主神經傳遞，使用 ATP、一氧化氮、VIP 等。","c":"9.3","f":"在腸道、血管、泌尿生殖道中，部分自主神經釋放 ATP、一氧化氮、血管活性腸胜肽（VIP）等，使平滑肌放鬆或收縮。","e":"陰莖勃起主要依賴副交感 NANC 神經釋放的一氧化氮。","m":"<b>不用 ACh 也不用 NE 的第三條路</b>。"},
"dualinn":{"t":"雙重支配 dual innervation","d":"同一器官同時受交感與副交感支配，關係可為<b>拮抗</b>（心臟、瞳孔、腸胃）、<b>互補</b>（唾液腺）、<b>協同</b>（生殖、排尿）。","c":"9.3","f":"<b>拮抗</b>：心臟（交感加快、副交感減慢）、瞳孔、腸胃。<b>互補</b>：唾液腺（兩者都促進分泌，成分不同）。<b>合作</b>：男性生殖（副交感勃起、交感射精）。只受交感支配的：多數血管、汗腺、豎毛肌、腎上腺髓質——靠增減交感活性來調控。","m":"<b>拮抗、互補、合作</b>；血管只靠交感調音量。"},
"vagaltone":{"t":"迷走張力 vagal tone","d":"安靜時迷走神經持續的抑制作用，使靜止心跳（約 70 次）低於節律點本身的速率（約 100 次）。","c":"9.3；第 13、14 章","f":"竇房結本身的速率約每分鐘 100 次，安靜時迷走神經持續釋放 ACh 減慢它；運動員迷走張力高，靜止心跳可低到 50 多次。","e":"心臟移植後神經被切斷，靜止心跳約 100 次。","m":"<b>迷走神經一直輕踩煞車</b>。"},
"baroreflex":{"t":"壓力感受器反射 baroreceptor reflex","d":"頸動脈竇與主動脈弓的壓力感受器偵測血壓，經延腦心血管中樞即時調整心跳與血管，維持血壓穩定。","c":"9.4；第 14 章","f":"血壓上升 → 動脈壁被撐開 → 感受器放電增加（經舌咽、迷走神經）→ 延腦 → 副交感↑、交感↓ → 心跳變慢、血管擴張 → 血壓回落；血壓下降則相反。是血壓的短期快速調節。","e":"從躺到站時血液往下積，壓力感受器反射立即加快心跳、收縮血管；長者反射較慢，易姿勢性低血壓頭暈。","m":"<b>血壓高 → 減速放鬆；血壓低 → 加速收縮</b>。"},
"vasovagal":{"t":"血管迷走性昏厥 vasovagal syncope","d":"情緒或疼痛（如看到血）引起副交感突然增強、交感撤退，心跳變慢、血壓下降，腦血流不足而暈倒。","c":"9.4","f":"強烈情緒、疼痛、長時間站立或用力解尿時，迷走神經突然增強、交感神經撤退 → 心跳變慢、周邊血管擴張 → 血壓下降 → 腦血流不足 → 短暫昏厥。","e":"感到頭暈、眼前發黑時立刻躺下或蹲下、抬高雙腿；抽血時躺著較安全。","m":"<b>迷走太強 → 心慢血管鬆 → 昏倒</b>。"},
"biofeedback":{"t":"生物回饋 biofeedback","d":"用儀器把心跳、血壓、肌肉張力等顯示出來，讓人學習有意識地調整它們的方法。","c":"9.4","f":"自主神經控制的功能平常感覺不到；透過儀器把它們即時顯示出來，配合放鬆呼吸等方法，人可以學會部分調控。","e":"用於緊張性頭痛、焦慮、高血壓、失禁的輔助治療。","m":"<b>看得到，才控制得到</b>。"}});
Object.assign(GL_ALIAS,{"節前":"pregang","節後":"pregang","節前神經元":"pregang","節後神經元":"pregang","自主神經節":"autogang","交感":"symp","副交感":"parasymp","交感神經鏈":"schain","交感鏈":"schain","終末神經節":"termgang","大量放電":"massact","腎上腺髓質":"admed","戰或逃":"fightflight","休息與消化":"restdigest","膽鹼性":"cholin","腎上腺素性":"cholin","腎上腺素性受體":"adrrec","α1":"alpha1","α2":"alpha2","β1":"beta1","β2":"beta2","β3":"beta3","β 阻斷劑":"betablock","致效劑":"agonist","拮抗劑":"agonist","阻斷劑":"agonist","NANC":"nanc","雙重支配":"dualinn","迷走張力":"vagaltone","壓力感受器反射":"baroreflex","血管迷走性昏厥":"vasovagal","生物回饋":"biofeedback"});

/* ---- end ch09 ---- */
/* ---- ch10 ---- */
Object.assign(GL,{"chemorec":{"t":"化學感受器 chemoreceptors","d":"偵測化學物質的感受器：味蕾、嗅覺，以及偵測血中 O₂、CO₂、pH 的頸動脈體與主動脈體。","c":"10.1；第 16 章","f":"化學物質與受體或通道結合 → 產生電訊號。外部：味覺、嗅覺。內部：頸動脈體與主動脈體（周邊，主要偵測 O₂↓）、延腦（中樞，偵測 CSF 的 H⁺／CO₂）→ 調節呼吸。","m":"<b>化學感受器：舌、鼻、血液</b>。"},
"photorec":{"t":"光感受器 photoreceptors","d":"偵測光的感受器：視網膜的桿細胞與錐細胞。","c":"10.7","f":"感光色素吸收光子 → 改變形狀 → G 蛋白連鎖反應 → 膜電位改變。桿細胞負責暗處、錐細胞負責顏色與細節。","e":"維生素 A 是感光色素的必需原料。","m":"<b>桿看暗、錐看色</b>。"},
"mechanorec":{"t":"機械感受器 mechanoreceptors","d":"偵測觸、壓、牽張、振動、聲音、重力的感受器。","c":"10.1","f":"機械力使細胞膜或纖毛變形 → 打開機械閘控離子通道 → 去極化。包括皮膚觸壓覺、肌梭與肌腱、內耳毛細胞（聽覺與平衡）、血管的壓力感受器。","m":"<b>拉、壓、彎 → 開通道</b>。"},
"nocirec":{"t":"痛覺（傷害）感受器 nociceptors","d":"偵測組織損傷或可能造成損傷的刺激（極端溫度、壓力、化學物質）的游離神經末梢。","c":"10.1、10.2","f":"多為游離神經末梢；強烈刺激與發炎物質（前列腺素、緩激肽、組織胺、H⁺、K⁺）使其敏感化。訊號經有髓鞘的 Aδ 纖維（快、刺痛、定位清楚）與無髓鞘的 C 纖維（慢、灼熱痛、定位模糊）傳入。","e":"NSAIDs 減少前列腺素，降低痛覺感受器的敏感化而止痛。","m":"<b>Aδ 快刺、C 慢燒</b>。"},
"thermorec":{"t":"溫度感受器 thermoreceptors","d":"皮膚中專門偵測「冷」與「熱」的感覺神經末梢。","c":"10.2","f":"TRPV1：熱（約 43°C 以上）與辣椒素；TRPM8：涼與薄荷醇。對溫度「變化」最敏感，持續同溫度會適應。","e":"薄荷讓人覺得涼、辣椒讓人覺得熱，就是化學物質直接打開溫度感受器的通道。","m":"<b>辣 → TRPV1（熱）；薄荷 → TRPM8（涼）</b>。"},
"lsne":{"t":"特定神經能量定律 law of specific nerve energies","d":"不論用什麼方式刺激，同一條感覺路徑傳到腦都只產生同一種感覺。","e":"眼睛被打一拳會「看到金星」——壓力刺激視網膜，大腦仍解讀成光。","c":"10.1","f":"感覺的「種類」不是由刺激決定，而是由被活化的感覺路徑與它到達的皮質區域決定。","m":"<b>走哪條線，就是哪種感覺</b>。"},
"adequate":{"t":"適當刺激 adequate stimulus","d":"感受器最敏感的那一種刺激（如視網膜對光）。","c":"10.1","f":"每種感受器對某一種能量的閾值最低；其他刺激需要非常強才能引起反應。","e":"光是視網膜的適當刺激；聲波是耳蝸毛細胞的適當刺激。","m":"<b>每種感受器都有最愛的刺激</b>。"},
"transduc":{"t":"轉導 transduction","d":"感受器把外界的能量（光、聲、壓力、化學物質）翻譯成神經能懂的電訊號。","c":"10.1","f":"刺激 → 受體或通道改變 → 離子流動 → 發生器電位（分級）→ 達閾值 → 感覺神經的動作電位。","m":"<b>轉導＝翻譯成電</b>。"},
"genpot":{"t":"發生器電位 generator potential","d":"感受器受刺激產生的分級去極化；越強越大，達閾值時在感覺神經上產生動作電位，頻率代表強度。","c":"10.1","f":"刺激越強，發生器電位越大 → 動作電位頻率越高；所以感覺強度是以「頻率」編碼。","m":"<b>強度 → 電位大小 → 發射頻率</b>。"},
"tonicrec":{"t":"緊張性、相位性感受器 tonic / phasic receptors","d":"<b>緊張性</b>：刺激持續時持續放電（痛覺、肌梭）。<b>相位性</b>：只在刺激開始（與結束）時放電，很快適應（觸壓覺、嗅覺）。","c":"10.1","f":"<b>緊張性</b>：慢適應，持續報告刺激還在（痛覺、肌梭、壓力感受器、本體感覺）。<b>相位性</b>：快適應，只在刺激開始或改變時放電（觸覺的梅斯納小體、巴齊尼小體、嗅覺）。","e":"戴上手錶不久就感覺不到它（相位性）；但痛不會因為持續就消失（緊張性），以免忽略傷害。","m":"<b>緊張性一直報、相位性報變化</b>。"},
"adaptation":{"t":"適應 adaptation","d":"持續相同刺激下感受器反應逐漸減少，使我們忽略不變的背景、注意變化。","c":"10.1","f":"感受器本身的離子通道變化，以及中樞神經的調整，使不變的刺激逐漸被忽略，讓注意力留給新的變化。","e":"進入廚房一會兒後聞不太到味道；穿上衣服很快就沒感覺。","m":"<b>習慣了就感覺不到</b>。"},
"freene":{"t":"游離神經末梢 free nerve endings","d":"沒有被囊包覆的感覺神經末梢，偵測痛、溫度、癢。","c":"10.2","w":"皮膚、黏膜、角膜、內臟，數量最多的感覺末梢。","f":"偵測痛覺、溫度、癢、粗略觸覺；多連到細的 Aδ 與 C 纖維。","m":"<b>裸露的末梢管痛、溫、癢</b>。"},
"meissner":{"t":"梅斯納小體、巴齊尼小體","d":"皮膚中兩種有「被囊」的觸覺感受器：梅斯納小體感覺輕觸，巴齊尼小體感覺深壓與振動。","c":"10.2","w":"梅斯納小體：指尖、嘴唇等無毛皮膚的真皮乳頭層（淺）。巴齊尼小體：真皮深層與皮下組織。","f":"兩者都是快適應（相位性）感受器；巴齊尼小體的層狀被囊像洋蔥，讓它對快速振動特別敏感。","m":"<b>梅斯納淺輕觸、巴齊尼深振動</b>。"},
"capsaicin":{"t":"辣椒素 capsaicin","d":"辣椒中的成分，活化熱感受器 TRPV1，所以吃辣會覺得「熱、痛」。","c":"10.2","f":"與 TRPV1 結合 → 打開陽離子通道 → 痛覺神經去極化，大腦解讀成「燒灼」；長時間使用使神經末梢耗竭 P 物質而變得不敏感。","e":"辣椒素藥膏用來治療帶狀疱疹後神經痛、關節痛；吃辣喝冷水沒用，喝牛奶（脂肪、酪蛋白）較能溶解辣椒素。","m":"<b>辣不是味道，是痛覺</b>。"},
"recfield":{"t":"感受野 receptive field","d":"一個感覺神經元負責的範圍。感受野越小、越密集，感覺越精細。","c":"10.2、10.8","f":"感受野小而重疊少、感受器密度高 → 能精確定位；感受野大 → 定位粗略但敏感。","e":"指尖與嘴唇感受野小、密度高，所以點字閱讀用指尖。","m":"<b>感受野越小，越精細</b>。"},
"twopoint":{"t":"兩點辨別閾 two-point threshold","d":"皮膚上同時碰觸兩點時，能分辨出是兩點的最短距離；指尖、嘴唇最小。","c":"10.2","f":"反映感受器的密度與感受野大小：指尖約 2–3 mm，背部可達 40 mm 以上。","e":"神經學檢查用來評估觸覺敏銳度與周邊神經功能。","m":"<b>指尖最靈、背最鈍</b>。"},
"latinh":{"t":"側抑制 lateral inhibition","d":"受刺激最強的神經元抑制周圍神經元，增強對比，使位置與邊緣更清楚。","c":"10.2、10.8","f":"中央被強烈刺激的神經元，經聯絡神經元抑制周圍較弱的神經元 → 中心與周圍的差異被放大 → 邊緣與位置更清楚。","e":"視網膜利用側抑制增強邊緣；觸覺定位、聽覺頻率辨別也用到它。","m":"<b>壓低旁邊，凸顯中間</b>。"},
"referred":{"t":"轉移痛 referred pain","d":"內臟的痛被感覺成來自同一脊髓節段支配的體表，因兩者的感覺纖維會聚到同一群脊髓神經元。","e":"心肌梗塞痛到左肩與左手臂內側；膽囊痛到右肩胛；闌尾炎初期痛在肚臍周圍。","c":"10.2","f":"內臟痛覺纖維與某些體表皮膚的痛覺纖維進入脊髓同一節段、會聚到同一群上行神經元；大腦習慣把訊號解讀成來自體表。","m":"<b>心 → 左臂、膽 → 右肩</b>。"},
"tastebud":{"t":"味蕾 taste buds","d":"位在舌乳頭等處、由味覺細胞（特化上皮細胞）組成的構造，約 10 天更新；接觸溶在唾液中的分子。","c":"10.3","w":"舌頭的蕈狀、輪廓、葉狀乳頭（絲狀乳頭沒有味蕾），以及軟顎、咽部；成人約 2,000–4,000 個。","f":"味覺細胞頂端的微絨毛伸出味孔，接觸溶解在唾液中的物質；訊號經顏面神經（舌前 2/3）、舌咽神經（舌後 1/3）、迷走神經傳到腦幹與島葉。","e":"缺鋅、化療、老化、口乾會使味覺下降，影響食慾與營養攝取。","m":"<b>味蕾約 10 天換新</b>；舌頭各區其實都能嚐五味。"},
"umami":{"t":"鮮味 umami","d":"第五種基本味道，由麩胺酸（味精）與核苷酸（IMP、GMP）引起，代表蛋白質。","n":"日文「旨味」，1908 年池田菊苗從昆布湯中發現。","c":"10.3","f":"由 T1R1＋T1R3 受體（G 蛋白偶聯）偵測麩胺酸；核苷酸（IMP 來自肉類與柴魚、GMP 來自香菇）有加乘作用。","e":"利用鮮味（昆布、香菇、番茄、柴魚）可以在減鹽時維持美味。","m":"<b>鮮味＝麩胺酸＋核苷酸的加乘</b>。"},
"gustducin":{"t":"味導素 gustducin","d":"味覺細胞中專門把「甜、苦、鮮」訊號傳下去的 G 蛋白。","c":"10.3","f":"受體活化 gustducin → 磷脂酶 C → IP₃ → 細胞內 Ca²⁺↑ → 打開 TRPM5 通道 → 去極化 → 釋放 ATP 給感覺神經。鹹味（Na⁺ 經通道進入）與酸味（H⁺）則直接靠離子通道。","m":"<b>甜苦鮮走 G 蛋白、鹹酸走通道</b>。"},
"olfactory":{"t":"嗅覺上皮、嗅球","d":"<b>嗅覺上皮</b>在鼻腔頂部，含嗅覺受體神經元（可更新）；<b>嗅球</b>在額葉下方，接收嗅神經並直接送到嗅覺皮質與邊緣系統。","c":"10.3","w":"嗅覺上皮在鼻腔頂部約 5 cm²；嗅覺神經元的軸突穿過篩板 → 嗅球（額葉下方）→ 嗅徑 → 嗅覺皮質與邊緣系統。","f":"嗅覺是唯一不先經視丘、直接到皮質與邊緣系統（杏仁核、海馬迴）的感覺，所以氣味特別容易勾起情緒與記憶。嗅覺神經元是少數能更新的神經元（約 1–2 個月）。","e":"感冒鼻塞時食物變得「沒味道」，因為風味大多來自嗅覺。","m":"<b>嗅覺不經視丘、直通情緒與記憶</b>。"},
"olfrec":{"t":"嗅覺受體 olfactory receptors","d":"約 350–400 種 G 蛋白偶聯受體，每個嗅覺神經元只表現一種；不同氣味活化不同組合。","n":"2004 年 Axel 與 Buck 因發現嗅覺受體家族獲諾貝爾獎。","c":"10.3","f":"氣味分子 → 嗅覺受體 → G 蛋白（G<sub>olf</sub>）→ cAMP ↑ → 打開陽離子通道 → 去極化。每種氣味活化一組受體，大腦依組合辨識上萬種氣味。","e":"2004 年 Axel 與 Buck 因發現嗅覺受體基因家族獲諾貝爾獎。","m":"<b>受體組合像密碼</b>。"},
"flavor":{"t":"風味 flavor","d":"食物的整體味道＝味覺＋嗅覺（鼻後嗅覺）＋口感與溫度；大部分來自嗅覺。","c":"10.3","f":"咀嚼時食物的揮發性分子由口腔後方往上進入鼻腔（鼻後嗅覺），與味覺、口感、溫度、辣度在大腦整合成「風味」。","e":"長者嗅覺退化常覺得食物無味而吃得少、加更多鹽；可用香料、香草、增加香氣與色彩來提升風味。","m":"<b>風味＝味覺＋嗅覺＋口感</b>，嗅覺占大部分。"},
"vestib":{"t":"前庭器 vestibular apparatus","d":"內耳負責平衡的部分：橢圓囊、球囊（直線加速、傾斜）與三個半規管（旋轉）。","c":"10.4","w":"內耳，位於耳蝸旁的骨迷路中。","f":"<b>耳石器</b>（橢圓囊、球囊）：偵測頭部傾斜與直線加速（電梯、汽車煞車）。<b>半規管</b>：偵測頭部旋轉的角加速度。訊號經前庭神經到腦幹前庭核與小腦，維持平衡、姿勢與眼球穩定。","m":"<b>耳石管直線與傾斜、半規管管旋轉</b>。"},
"endolymph":{"t":"內淋巴、外淋巴 endolymph / perilymph","d":"內耳有兩種液體：膜迷路裡面的內淋巴（鉀很高，像細胞內液），以及外面的外淋巴（鈉高，像細胞外液）。","c":"10.4、10.5","f":"內淋巴的高 K⁺ 讓毛細胞纖毛彎曲時 K⁺ 流<b>入</b>細胞造成去極化——這是少數 K⁺ 流入使細胞興奮的例子。","e":"內淋巴過多（內淋巴水腫）是梅尼爾氏症的特徵：眩暈、耳鳴、聽力下降；常建議限鈉、少咖啡因。","m":"<b>內淋巴高鉀</b>。"},
"haircell":{"t":"毛細胞 hair cells","d":"內耳的機械感受細胞，頂端有靜纖毛；纖毛往動纖毛（最高處）方向彎曲 → K⁺ 流入去極化。","c":"10.4、10.5","f":"靜纖毛之間以尖端連結相連；往最長的動纖毛方向彎曲 → 拉開機械閘控通道 → K⁺ 流入 → 去極化 → 釋放神經傳遞物質增加；反方向彎曲 → 過極化。","e":"噪音、某些抗生素（胺基醣苷類）、老化會傷害毛細胞，人類的毛細胞不能再生。","m":"<b>往高的倒 → 興奮</b>。"},
"otolith":{"t":"耳石、耳石器 otoliths","d":"內耳中像細沙一樣的碳酸鈣小晶體，讓平衡器官感覺到重力與加速。","c":"10.4","f":"耳石較重，頭傾斜或加速時會落後或滑動，拖動膠質膜 → 彎曲毛細胞纖毛。","e":"耳石脫落掉進半規管 → 良性陣發性姿勢性眩暈（翻身、抬頭時天旋地轉），可用耳石復位術治療。","n":"oto-＝耳、lith＝石。"},
"utricle":{"t":"橢圓囊、球囊 utricle / saccule","d":"耳石器。<b>橢圓囊</b>偵測水平方向的加速與傾斜；<b>球囊</b>偵測垂直方向的加速。","c":"10.4","f":"橢圓囊的感覺斑大致水平，對水平加速與頭部傾斜最敏感；球囊的感覺斑大致垂直，對上下加速（電梯）最敏感。","m":"<b>橢圓囊管水平、球囊管垂直</b>。"},
"semicirc":{"t":"半規管 semicircular canals","d":"三個互相垂直的管道，內淋巴在頭部旋轉時推動壺腹頂，偵測旋轉加速。","c":"10.4","f":"三個管道互相垂直，分別偵測三個平面的旋轉；旋轉開始時內淋巴因慣性落後，推動壺腹頂 → 毛細胞纖毛彎曲。持續等速旋轉時內淋巴跟上，訊號就消失。","e":"轉圈停下時內淋巴繼續流動，所以停下來反而覺得還在轉。","m":"<b>三個互相垂直＝三度空間的旋轉</b>。"},
"cupula":{"t":"壺腹頂 cupula","d":"半規管壺腹中包住毛細胞纖毛的膠質帽，被內淋巴推動時使纖毛彎曲。","c":"10.4","f":"像擋在管道中的一扇膠質門；內淋巴流動時推動它，使埋在裡面的毛細胞纖毛彎曲。","m":"<b>壺腹頂＝內淋巴推動的門</b>。"},
"vertigo":{"t":"眩暈、眼球震顫 vertigo / nystagmus","d":"<b>眩暈</b>：天旋地轉的感覺，前庭訊號與視覺不一致時產生。<b>眼球震顫</b>：眼球不自主來回擺動。","c":"10.4","f":"前庭、視覺、本體感覺三方訊息不一致時，大腦產生旋轉感；前庭–眼反射異常造成眼球不自主來回跳動（眼球震顫）。","e":"暈車暈船是前庭訊號與視覺不一致；梅尼爾氏症、耳石脫落、前庭神經炎、腦幹或小腦病變都會引起眩暈。","m":"<b>眼睛和耳朵吵架 → 頭暈</b>。"},
"tympanic":{"t":"鼓膜 tympanic membrane","d":"外耳與中耳之間的薄膜，受聲波振動。","c":"10.5","w":"外耳道的底端。","f":"聲波使鼓膜振動，振動傳給附著在上面的槌骨。","e":"中耳炎積液或鼓膜破孔會降低傳導，造成傳導性聽力損失。","m":"<b>鼓膜＝耳朵的鼓皮</b>。"},
"ossicles":{"t":"聽小骨 ossicles","d":"中耳的三塊小骨：槌骨、砧骨、鐙骨，把鼓膜振動放大約 20 倍傳到卵圓窗。","c":"10.5","f":"槌骨 → 砧骨 → 鐙骨形成槓桿；加上鼓膜面積比卵圓窗大很多，振動壓力被放大，克服由空氣進入液體時的能量損失。兩條小肌肉（鐙骨肌、鼓膜張肌）在巨大聲響時收縮保護內耳。","e":"耳硬化症使鐙骨固定，造成傳導性耳聾。","m":"<b>槌 → 砧 → 鐙</b>（鐙骨是人體最小的骨頭）。"},
"ovalwin":{"t":"卵圓窗、圓窗 oval / round window","d":"<b>卵圓窗</b>：鐙骨踩著的內耳入口，振動由此進入耳蝸外淋巴。<b>圓窗</b>：耳蝸另一端的膜，讓壓力波釋放回中耳。","c":"10.5","f":"鐙骨推動卵圓窗 → 耳蝸外淋巴產生壓力波 → 基底膜振動 → 壓力最後由圓窗向外鼓出釋放（液體無法壓縮，需要另一個出口）。","m":"<b>卵圓窗進、圓窗出</b>。"},
"eust":{"t":"耳咽管 auditory (Eustachian) tube","d":"連接中耳與咽部的管道，吞嚥或打哈欠時打開，平衡中耳與外界的氣壓。","c":"10.5","f":"平時關閉，吞嚥、打哈欠時打開，讓中耳氣壓與外界相同，鼓膜才能自由振動；也讓中耳分泌物流向咽部。","e":"飛機下降時耳朵悶痛，吞口水或打哈欠可緩解；兒童的耳咽管短而水平，咽部感染容易蔓延成中耳炎。","n":"又稱歐氏管，以 16 世紀義大利解剖學家 Eustachi 命名。"},
"cochlea":{"t":"耳蝸 cochlea","d":"內耳盤繞約 2¾ 圈的聽覺器官，內有基底膜與柯蒂氏器。","n":"拉丁文「蝸牛殼」。","c":"10.5","f":"內部分成三條管道：前庭階、蝸管（中階，含內淋巴與柯蒂氏器）、鼓階。聲波使基底膜振動，柯蒂氏器的毛細胞把振動轉成神經訊號，經耳蝸神經 → 腦幹 → 視丘內側膝狀核 → 顳葉聽覺皮質。","m":"<b>耳蝸＝把聲音變成電的蝸牛殼</b>。"},
"basilar":{"t":"基底膜 basilar membrane（耳蝸）","d":"耳蝸蝸管底部的膜，上面坐著柯蒂氏器；底部窄硬對高音、頂部寬軟對低音（位置理論）。","c":"10.5","f":"不同頻率的聲音使基底膜不同位置振動最大（位置編碼）：靠近卵圓窗的底部窄而硬 → 高音；耳蝸頂部寬而軟 → 低音。","e":"老年性聽力損失常從高頻開始，因為底部毛細胞最先受損。","m":"<b>底高頂低</b>。"},
"corti":{"t":"柯蒂氏器 organ of Corti（spiral organ）","d":"耳蝸基底膜上的聽覺感受器，由內毛細胞（傳訊）、外毛細胞（放大）與支持細胞組成，纖毛抵住上方的覆膜。","c":"10.5","w":"耳蝸蝸管內、基底膜之上，上方覆蓋著蓋膜。","f":"基底膜振動 → 毛細胞纖毛與蓋膜相對移動而彎曲 → 內毛細胞（約 3,500 個）把訊號傳給聽神經；外毛細胞會伸縮放大振動，提高敏感度與頻率辨別。","n":"以 19 世紀義大利解剖學家 Alfonso Corti 命名。","m":"<b>內毛細胞傳訊、外毛細胞放大</b>。"},
"deaf":{"t":"傳導性、感音神經性耳聾","d":"聽力損失分兩大類：聲音「傳不進去」叫傳導性，內耳或聽神經「收不到」叫感音神經性。","c":"10.5","f":"<b>傳導性</b>：外耳道、鼓膜、聽小骨的問題，骨傳導仍正常。<b>感音神經性</b>：毛細胞或聽神經受損（噪音、老化、耳毒性藥物、遺傳），重度者可用人工電子耳。","m":"<b>傳導性：路塞住；感音神經性：收音器壞了</b>。"},
"cornea":{"t":"角膜 cornea","d":"眼球最前方透明、無血管的部分，提供約 2/3 的折射力（固定）。","c":"10.6","f":"表面弧度固定、透明，提供大部分的折射力；沒有血管，養分來自房水與淚液，但有大量神經末梢，非常敏感。","e":"近視雷射手術就是削薄角膜改變曲度；維生素 A 嚴重缺乏 → 角膜乾燥、軟化甚至穿孔。","m":"<b>角膜：最主要的固定鏡頭</b>。"},
"lens":{"t":"水晶體 lens","d":"虹膜後方的雙凸透明構造，提供約 1/3 的折射力，可改變形狀調節焦距。變混濁＝白內障。","c":"10.6","f":"由排列整齊、不含胞器的透明細胞組成，富含晶體蛋白；靠睫狀肌與懸韌帶改變弧度，負責「調焦」。","e":"老化、糖尿病（山梨醇堆積）、紫外線、抽菸使晶體蛋白變性聚集 → 白內障。","m":"<b>水晶體：可變焦的鏡頭</b>。"},
"iris":{"t":"虹膜、瞳孔 iris / pupil","d":"<b>虹膜</b>是眼睛有顏色的部分，含環狀肌（副交感，縮小瞳孔）與輻射狀肌（交感，放大瞳孔）；中間的孔是<b>瞳孔</b>。","c":"10.6；第 9 章","f":"<b>瞳孔括約肌</b>（環狀，副交感，ACh）收縮 → 瞳孔縮小；<b>瞳孔放大肌</b>（輻射狀，交感，α₁）收縮 → 瞳孔放大。強光時瞳孔反射縮小，保護視網膜並增加景深。","e":"有機磷中毒、鴉片類 → 瞳孔縮小；阿托平、驚嚇 → 瞳孔放大。","m":"<b>副交感縮、交感放</b>。"},
"ciliary":{"t":"睫狀體、懸韌帶 ciliary body / suspensory ligament","d":"<b>睫狀體</b>含睫狀肌並分泌房水；<b>懸韌帶</b>連接睫狀體與水晶體。看近時睫狀肌收縮、懸韌帶放鬆、水晶體變圓。","c":"10.6","f":"睫狀肌收縮 → 睫狀體往前內縮 → 懸韌帶放鬆 → 水晶體因自身彈性變圓 → 看近；睫狀肌放鬆 → 懸韌帶拉緊 → 水晶體變扁 → 看遠。睫狀體上皮也分泌房水。","m":"<b>看近：肌肉縮、韌帶鬆、水晶體圓</b>。"},
"aqueous":{"t":"房水、玻璃體 aqueous humor / vitreous body","d":"<b>房水</b>：角膜與水晶體之間的液體，由睫狀體分泌、經許萊姆氏管排出；排出受阻 → 青光眼。<b>玻璃體</b>：水晶體後的膠狀物。","c":"10.6","f":"房水供應角膜與水晶體養分並維持眼壓；由睫狀體持續分泌 → 經瞳孔到前房 → 經前房角的許萊姆氏管回到靜脈。玻璃體是水晶體後方的膠狀物，撐住眼球形狀。","e":"房水排出受阻 → 眼壓升高 → 青光眼。","m":"<b>房水不斷流動、玻璃體固定不換</b>。"},
"accom":{"t":"調節作用 accommodation","d":"水晶體改變形狀以對焦遠近：看近時睫狀肌收縮 → 懸韌帶鬆 → 水晶體變圓。","c":"10.6","f":"看近物時三件事同時發生（近反射）：水晶體變圓、瞳孔縮小、兩眼內聚；由副交感神經控制。","e":"長時間看近（手機、書本）睫狀肌持續收縮，容易眼睛疲勞；看遠方可以讓它放鬆。","m":"<b>看近：變圓、縮瞳、鬥雞眼</b>。"},
"refraction":{"t":"折射 refraction","d":"光線進入密度不同的介質時方向彎折；眼睛靠角膜與水晶體折射，在視網膜上成像。","c":"10.6","f":"光從空氣進入角膜時彎折最多（兩者密度差最大），水晶體再微調；正常眼睛讓遠處的光剛好聚焦在視網膜上，成像是上下左右顛倒的，由大腦轉正。","m":"<b>角膜大轉彎、水晶體微調</b>。"},
"myopia":{"t":"近視、遠視 myopia / hyperopia","d":"<b>近視</b>：眼球太長或折射太強，成像在視網膜前，看遠模糊，用凹透鏡。<b>遠視</b>：眼球太短，成像在後，用凸透鏡。","c":"10.6","f":"近視：眼軸太長或折射太強 → 遠方影像聚焦在視網膜前方 → 凹透鏡（發散）矯正。遠視：眼軸太短或折射太弱 → 聚焦在視網膜後方 → 凸透鏡（會聚）矯正。","e":"台灣學童近視盛行率高，戶外活動與減少長時間近距離用眼有助於預防。","m":"<b>近視凹、遠視凸</b>。"},
"presby":{"t":"老花眼 presbyopia","d":"年紀增長水晶體失去彈性，看近時無法變圓，近點變遠；用凸透鏡（老花眼鏡）。","n":"presby-＝老、-opia＝眼睛（視力）。","c":"10.6","f":"水晶體隨年齡變硬、睫狀肌力量下降 → 看近時無法變圓 → 近點越來越遠，通常 40 多歲開始。","m":"<b>老花＝水晶體變硬</b>，和近視可以同時存在。"},
"astig":{"t":"散光 astigmatism","d":"角膜或水晶體不同方向的曲度不同，使某些方向的線條模糊；用柱狀透鏡矯正。","c":"10.6","f":"正常角膜像籃球各方向弧度相同；散光的角膜像橄欖球，不同方向的焦點落在不同位置，所以某些方向的線看得清楚、某些模糊。","n":"a-＝沒有、stigma＝點：光線無法聚成一個點。","m":"<b>籃球形正常、橄欖球形散光</b>。"},
"glaucoma":{"t":"青光眼 glaucoma","d":"房水排出受阻使眼壓升高，壓迫並損傷視神經，造成視野缺損甚至失明。","c":"10.6","f":"多數是房水排出慢、眼壓升高 → 長期壓迫視神經盤 → 神經節細胞的軸突死亡 → 視野從周邊開始缺損，早期常無症狀，損傷無法恢復。","e":"40 歲以上、有家族史、高度近視者應定期量眼壓與檢查視神經。","m":"<b>青光眼＝偷走視力的小偷</b>（先缺周邊）。"},
"cataract":{"t":"白內障 cataract","d":"水晶體變混濁，與老化、糖尿病、紫外線有關；以手術更換人工水晶體。","c":"10.6","f":"晶體蛋白氧化、醣化、聚集 → 水晶體混濁 → 視力模糊、畏光、顏色變淡。","e":"糖尿病高血糖使水晶體中山梨醇堆積而加速白內障；富含抗氧化物（維生素 C、E、葉黃素）的飲食可能有幫助。","m":"<b>白內障＝鏡頭起霧</b>。"},
"retina":{"t":"視網膜 retina","d":"眼球最內層的神經組織，含感光細胞（桿、錐）、雙極細胞、神經節細胞，把光轉成神經訊號。","c":"10.7","w":"眼球最內層，貼在脈絡膜（富含血管）上。","f":"光線要先穿過神經節細胞、雙極細胞才到達最外層的感光細胞（倒置的構造）；感光細胞 → 雙極細胞 → 神經節細胞（軸突組成視神經）。色素上皮層吸收多餘光線、回收視網醛、吞噬感光細胞脫落的外節。","e":"糖尿病視網膜病變是成人失明的重要原因；控制血糖與血壓可延緩。","m":"<b>感光 → 雙極 → 神經節 → 視神經</b>。"},
"rods":{"t":"桿細胞、錐細胞 rods / cones","d":"視網膜上兩種感光細胞：桿細胞負責暗處、錐細胞負責顏色與細節。","c":"10.7","f":"桿細胞：數量多、非常敏感、許多會聚到一個神經節細胞（敏感但模糊），只有一種色素（視紫質），只看黑白。錐細胞：集中在中央小窩、一對一連接（清晰），三種色素看顏色，需要較亮的光。","e":"夜晚看星星時，用眼角（周邊視網膜）看反而看得到暗的星。","m":"<b>桿：暗、黑白、周邊；錐：亮、彩色、中央</b>。"},
"rhodopsin":{"t":"視紫質 rhodopsin","d":"桿細胞的感光色素＝視蛋白＋11-順式視網醛（來自維生素 A）；光使其漂白並啟動視覺訊號。","c":"10.7","f":"光使 11-順式視網醛變成全反式 → 視紫質活化 → 轉導素 → 磷酸二酯酶分解 cGMP → 鈉通道關閉 → 桿細胞<b>過極化</b> → 減少釋放麩胺酸 → 訊號傳出。之後全反式視網醛與視蛋白分離（漂白），再由色素上皮細胞轉回 11-順式重新組合。","m":"<b>視紫質＝視蛋白＋11-順式視網醛</b>；照光後漂白。"},
"retinal":{"t":"視網醛 retinal","d":"維生素 A 的醛類形式，是感光色素中真正「吸收光」的部分。","c":"10.7；營養學","f":"視網醇（運送型）在眼睛氧化成視網醛；11-順式視網醛吸收光子後變成全反式，引起視蛋白形狀改變，視覺訊號從這裡開始。","m":"<b>醛看東西</b>（醇運送、酸管基因）。"},
"transducin":{"t":"轉導素 transducin","d":"視紫質活化的 G 蛋白，進而活化磷酸二酯酶分解 cGMP，使鈉通道關閉。","c":"10.7","f":"活化的視紫質讓轉導素換上 GTP → 活化 cGMP 磷酸二酯酶 → cGMP 下降 → cGMP 閘控鈉通道關閉。一個視紫質可活化數百個轉導素，訊號被大幅放大，所以桿細胞能偵測單一光子。","m":"<b>光 → 視紫質 → 轉導素 → cGMP↓ → 鈉通道關</b>。"},
"darkadapt":{"t":"暗適應、光適應 dark / light adaptation","d":"<b>暗適應</b>：進入暗處後視紫質逐漸再生，敏感度增加約 10 萬倍以上（20–30 分鐘）。<b>光適應</b>：進入亮處後視紫質漂白，敏感度下降（較快）。","c":"10.7","f":"暗適應：視紫質逐漸再生，加上瞳孔放大、神經調整，約 20–30 分鐘大致完成。光適應：視紫質大量漂白、錐細胞接手，約數分鐘內完成。","e":"從大太陽下走進電影院，一開始看不見，慢慢才看得清楚；維生素 A 不足時暗適應變慢。","m":"<b>暗適應慢、光適應快</b>。"},
"nightblind":{"t":"夜盲症 night blindness","d":"維生素 A 缺乏使視紫質再生不足，在暗處或黃昏看不清楚；是維生素 A 缺乏最早的症狀之一。","c":"10.7；營養學","f":"視網醛不足 → 視紫質再生不夠 → 桿細胞在暗處失去敏感度；錐細胞在亮處仍可工作，所以白天看似正常。","e":"補充維生素 A 後可改善；嚴重缺乏進一步出現乾眼症、畢托氏斑、角膜軟化而失明。","m":"<b>夜盲是維生素 A 缺乏最早的徵兆</b>。"},
"fovea":{"t":"中央小窩、黃斑部 fovea centralis / macula lutea","d":"<b>黃斑部</b>是視網膜中央的黃色區域（含葉黃素、玉米黃素），其中心的<b>中央小窩</b>只有錐細胞，是視覺最清晰處。","c":"10.7","w":"視網膜正中央、正對視軸的位置；黃斑部約 5 mm，中央小窩在它的中心。","f":"中央小窩只有錐細胞、密度最高、而且上層的神經細胞被推開，光線直接照到錐細胞 → 視力最清晰。看東西時眼睛會把影像對準這裡。","e":"老年性黃斑部病變使中央視力喪失；葉黃素與玉米黃素集中在黃斑部，能過濾藍光、抗氧化。","m":"<b>中央小窩＝最清楚的焦點</b>。"},
"trichrom":{"t":"三色理論 trichromatic theory","d":"三種錐細胞分別對藍、綠、紅光最敏感，腦依三者被活化的比例判斷顏色。","c":"10.7","f":"S（短波，藍）、M（中波，綠）、L（長波，紅）三種錐細胞的吸收範圍重疊；大腦依三者的相對活化比例調配出所有顏色，就像螢幕的 RGB。","m":"<b>三原色 RGB</b>。"},
"colorblind":{"t":"色盲 color blindness","d":"缺少某種錐細胞或光視素異常；最常見的紅綠色盲為 X 性聯隱性遺傳，男性較多。","c":"10.7","f":"紅與綠光視素的基因位於 X 染色體 → X 性聯隱性遺傳：男性只有一條 X，一個缺陷基因就會表現；女性需要兩條都有缺陷。","e":"台灣男性紅綠色盲約 5%、女性不到 1%。","m":"<b>紅綠色盲：X 性聯、男多女少</b>。"},
"blindspot":{"t":"盲點 blind spot（視神經盤）","d":"視神經離開眼球處，沒有感光細胞，所以看不到落在這裡的影像。","c":"10.7","w":"視神經盤，位於中央小窩鼻側約 15 度處，也是視網膜血管進出的地方。","f":"這裡沒有桿細胞與錐細胞；平常兩眼視野互補，加上大腦「補圖」，所以不會察覺。","e":"眼底鏡檢查視神經盤可看出青光眼、顱內壓升高（視乳頭水腫）。","m":"<b>神經出口＝沒有感光細胞</b>。"},
"chiasma":{"t":"視交叉 optic chiasma","d":"兩條視神經在腦下方的交會處，兩眼鼻側視網膜的纖維在此交叉到對側，使左視野送到右腦。","c":"10.8；第 11 章","f":"兩眼<b>鼻側</b>視網膜（看外側視野）的纖維交叉，<b>顳側</b>的不交叉 → 左視野的訊息全部送到右腦、右視野送到左腦。","e":"腦下垂體腫瘤壓迫視交叉 → 兩眼外側視野缺損（雙顳側偏盲）。","m":"<b>鼻側交叉、顳側不交叉</b>。"},
"lgn":{"t":"外側膝狀核 lateral geniculate nucleus","d":"視丘中負責轉送視覺訊號到枕葉視覺皮質的神經核。","c":"10.8","f":"視神經纖維在視丘的外側膝狀核換神經元，再經視放射到枕葉；外側膝狀核也接收皮質回饋，調整傳送的訊息。","m":"<b>看見的轉運站：外側膝狀核；聽見的：內側膝狀核</b>。"},
"visualcx":{"t":"視覺皮質 visual cortex","d":"枕葉的視覺處理區；之後分腹側（往顳葉：是什麼）與背側（往頂葉：在哪裡、怎麼動）兩條路徑。","c":"10.8","w":"<b>枕葉</b>，初級視覺皮質在距狀溝兩側。","f":"初級視覺皮質處理線條方向、邊緣、運動；再分成腹側路徑（往顳葉，辨認物體與臉孔：是什麼）與背側路徑（往頂葉，位置與動作：在哪裡）。","e":"枕葉中風 → 對側視野缺損；顳葉梭狀迴受損 → 認不出熟人的臉（臉盲）。","m":"<b>腹側問「是什麼」、背側問「在哪裡」</b>。"}});
Object.assign(GL_ALIAS,{"化學感受器":"chemorec","光感受器":"photorec","機械感受器":"mechanorec","痛覺感受器":"nocirec","傷害感受器":"nocirec","溫度感受器":"thermorec","特定神經能量定律":"lsne","適當刺激":"adequate","轉導":"transduc","發生器電位":"genpot","感受器電位":"genpot","緊張性":"tonicrec","相位性":"tonicrec","適應":"adaptation","游離神經末梢":"freene","梅斯納小體":"meissner","巴齊尼小體":"meissner","辣椒素":"capsaicin","感受野":"recfield","兩點辨別":"twopoint","兩點辨別閾":"twopoint","側抑制":"latinh","轉移痛":"referred","味蕾":"tastebud","鮮味":"umami","味導素":"gustducin","嗅覺上皮":"olfactory","嗅球":"olfactory","嗅覺受體":"olfrec","風味":"flavor","前庭器":"vestib","內淋巴":"endolymph","外淋巴":"endolymph","毛細胞":"haircell","耳石":"otolith","橢圓囊":"utricle","球囊":"utricle","半規管":"semicirc","壺腹頂":"cupula","眩暈":"vertigo","眼球震顫":"vertigo","鼓膜":"tympanic","聽小骨":"ossicles","卵圓窗":"ovalwin","圓窗":"ovalwin","耳咽管":"eust","耳蝸":"cochlea","柯蒂氏器":"corti","傳導性耳聾":"deaf","感音神經性":"deaf","角膜":"cornea","水晶體":"lens","虹膜":"iris","瞳孔":"iris","睫狀肌":"ciliary","睫狀體":"ciliary","懸韌帶":"ciliary","房水":"aqueous","玻璃體":"aqueous","調節作用":"accom","折射":"refraction","近視":"myopia","遠視":"myopia","老花":"presby","老花眼":"presby","散光":"astig","青光眼":"glaucoma","白內障":"cataract","視網膜":"retina","桿細胞":"rods","錐細胞":"rods","視紫質":"rhodopsin","視網醛":"retinal","轉導素":"transducin","暗適應":"darkadapt","光適應":"darkadapt","夜盲症":"nightblind","中央小窩":"fovea","黃斑部":"fovea","三色理論":"trichrom","色盲":"colorblind","盲點":"blindspot","視交叉":"chiasma","外側膝狀核":"lgn","視覺皮質":"visualcx"});

/* ---- end ch10 ---- */
/* ---- ch07 ---- */
Object.assign(GL,{"cns":{"t":"中樞神經系統 central nervous system（CNS）","d":"神經系統的「指揮總部」：腦和脊髓。","c":"7.1；第 8 章","w":"腦在顱骨內、脊髓在脊椎管內，外面包著腦膜，浸在腦脊髓液中。","f":"接收全身送來的感覺訊息 → 整合、判斷、記憶 → 發出命令到肌肉與腺體。","e":"脊髓損傷時，損傷部位以下的感覺與運動和大腦失去聯繫。","m":"<b>中樞＝腦＋脊髓，其他都是周邊</b>。"},
"pns":{"t":"周邊神經系統 peripheral nervous system（PNS）","d":"從腦和脊髓延伸到全身的「電線」，負責把訊息送進送出。","c":"7.1；第 9 章","f":"<b>傳入</b>（感覺）：把感受器訊號送進中樞。<b>傳出</b>：體神經（骨骼肌，隨意）＋自主神經（心肌、平滑肌、腺體，不隨意；交感、副交感）。包括 12 對腦神經與 31 對脊神經。","e":"糖尿病周邊神經病變常從腳開始麻木，因為最長的神經最容易受損。","m":"<b>周邊＝電線；體神經管骨骼肌、自主神經管內臟</b>。"},
"somatic":{"t":"體神經系統 somatic nervous system","d":"支配<b>骨骼肌</b>、可隨意控制的周邊神經。","c":"7.1","f":"運動神經元從脊髓（或腦幹）直接一條連到骨骼肌，中間沒有神經節，末梢釋放乙醯膽鹼作用在菸鹼型受體 → 永遠是興奮。","e":"舉手、走路、說話都是體神經的命令；反射（如膝跳反射）也走體神經。","m":"<b>一條到底、只會興奮</b>（自主神經要兩條、可興奮可抑制）。"},
"autonomic":{"t":"自主神經系統 autonomic nervous system","d":"管理內臟、不必用意志控制的神經系統，分成交感（戰或逃）與副交感（休息與消化）。","c":"第 9 章","f":"從中樞到目標器官要兩個神經元：節前神經元 → 自主神經節 → 節後神經元。調節心跳、血壓、消化、排尿、流汗、瞳孔等。","e":"緊張時心跳加快、口乾、手心出汗是交感神經；飯後想睡、腸胃蠕動是副交感。","m":"<b>交感＝打仗、副交感＝吃飯休息</b>。"},
"ganglion":{"t":"神經節 ganglion","d":"周邊神經上一團一團的神經細胞本體，像中途轉運站。","c":"7.1","w":"背根神經節（感覺神經元本體）、自主神經節（交感鏈、器官附近的副交感神經節）。","f":"感覺神經節只是放細胞本體；自主神經節則是節前與節後神經元之間的突觸轉接站。","m":"<b>周邊叫「節」、中樞叫「核」</b>。"},
"nissl":{"t":"尼氏小體 Nissl bodies","d":"神經元細胞本體中大量的粗糙內質網，染色後呈顆粒狀，負責大量合成蛋白質。","n":"以德國神經學家 Franz Nissl 命名。","c":"7.1","w":"神經元的細胞本體與樹突基部（軸突與軸丘沒有）。","f":"神經元要不斷製造神經傳遞物質相關酵素、受體、通道蛋白，並經軸突運輸送到遠處，所以粗糙內質網特別發達。","e":"軸突受傷後，細胞本體的尼氏小體會散開減少（染色質溶解），反映細胞正忙著修復。"},
"hillock":{"t":"軸丘 axon hillock","d":"軸突從細胞本體長出來的那個小丘，是神經元「決定要不要發射」的地方。","c":"7.1、7.7","f":"樹突與細胞本體收到的興奮與抑制訊號在這裡加總；若去極化達到閾值，起始段大量的電壓閘控 Na⁺ 通道打開 → 產生動作電位。","m":"<b>軸丘＝扣板機的地方</b>。"},
"axtrans":{"t":"軸突運輸 axonal transport","d":"神經元用微管當軌道，在細胞本體與遙遠的軸突末梢之間搬運貨物。","e":"破傷風毒素、狂犬病毒、疱疹病毒就是搭逆向運輸進入中樞神經系統。","c":"7.1","f":"<b>順向</b>（本體 → 末梢）：驅動蛋白 kinesin 搬運胞器、酵素、突觸小泡材料。<b>逆向</b>（末梢 → 本體）：動力蛋白 dynein 把回收物與神經營養因子送回本體。","m":"<b>kinesin 往外、dynein 往回</b>。"},
"sensoryn":{"t":"感覺（傳入）神經元 sensory / afferent neuron","d":"把感受器的訊號傳<b>入</b>中樞，多為偽單極神經元，細胞本體在背根神經節。","c":"7.1","f":"把皮膚、肌肉、內臟、特殊感覺器官的訊號傳入中樞；細胞本體在脊髓旁的背根神經節（或腦神經節），從背根進入脊髓。","m":"<b>感覺走背根、運動走腹根</b>。"},
"motorn":{"t":"運動（傳出）神經元 motor / efferent neuron","d":"把中樞的命令傳<b>出</b>到肌肉或腺體，多為多極神經元。","c":"7.1","f":"細胞本體在中樞（脊髓腹角或腦幹）；體運動神經元直接支配骨骼肌，自主運動神經元則經過神經節再到內臟。","e":"小兒麻痺病毒、漸凍人（肌萎縮性脊髓側索硬化症）破壞運動神經元 → 肌肉無力萎縮。"},
"intern":{"t":"聯絡神經元 interneuron","d":"完全位於腦和脊髓裡、負責連接與整合的「中間人」神經元，占神經元的絕大多數。","c":"7.1","f":"在感覺與運動神經元之間做加總、比較、抑制與記憶，讓反應不只是單純反射。","e":"膝跳反射只有感覺→運動兩個神經元；縮手反射則經過聯絡神經元。"},
"neuroglia2":{"t":"神經膠細胞 neuroglia","d":"神經系統裡負責照顧、保護、絕緣神經元的「後勤人員」。","c":"7.1","f":"中樞：星狀膠細胞、寡突膠細胞（中樞髓鞘）、微膠細胞、室管膜細胞。周邊：許旺細胞（周邊髓鞘）、衛星細胞。","n":"glia 來自希臘文「膠水」，早期認為它只是把神經元黏在一起。","m":"<b>中樞四種、周邊兩種</b>。"},
"satellite":{"t":"衛星細胞 satellite cells","d":"包圍在周邊神經節細胞本體外面的小支持細胞，像衛星圍繞行星。","c":"7.1","f":"維持神經元周圍的化學環境、提供支持；功能類似中樞的星狀膠細胞。"},
"astro":{"t":"星狀膠細胞 astrocytes","d":"中樞最多的膠細胞，呈星狀：誘導血腦障壁、清除多餘 K⁺ 與麩胺酸、供應神經元乳酸、參與突觸功能與疤痕形成。","c":"7.1","w":"中樞神經系統，分布在神經元與微血管之間，「腳」包住微血管。","f":"①誘導並維持<b>血腦障壁</b>；②回收突觸釋放的<b>麩胺酸</b>與多餘的 K⁺；③把肝醣分解成乳酸供應神經元；④參與突觸形成與調控；⑤受傷後形成疤痕（膠質增生）。","n":"astro-＝星星，形狀呈星芒狀。","m":"<b>星狀膠細胞＝神經元的管家</b>。"},
"microglia":{"t":"微膠細胞 microglia","d":"中樞神經系統裡的「駐腦免疫細胞」。","c":"7.1","f":"平時巡邏監測，遇到感染、損傷或退化產物時活化，吞噬病原與碎片並釋放發炎物質。","e":"阿茲海默症、多發性硬化症中微膠細胞過度活化，可能加重神經損傷。","m":"<b>微膠細胞＝腦中的巨噬細胞</b>。"},
"ependymal":{"t":"室管膜細胞 ependymal cells","d":"襯在腦室與脊髓中央管的細胞，參與腦脊髓液的形成與流動。","c":"7.1；第 8 章","w":"腦室與脊髓中央管的內壁。","f":"在脈絡叢中與微血管一起製造<b>腦脊髓液</b>；表面的纖毛擺動幫助腦脊髓液流動。","m":"<b>室管膜＝腦室的內襯</b>。"},
"neurilemma":{"t":"神經膜 neurilemma","d":"許旺細胞最外圈含有細胞核與細胞質的那一層，是周邊神經能再生的關鍵。","c":"7.1","f":"周邊神經被切斷後，遠端軸突退化，但神經膜形成一條「再生管」，引導近端長出的新軸突沿著原路回到目標。中樞的寡突膠細胞沒有神經膜，加上抑制性物質，中樞神經很難再生。","m":"<b>周邊能再生（有神經膜）、中樞難</b>。"},
"ranvier":{"t":"蘭氏結 nodes of Ranvier","d":"兩段髓鞘之間的裸露軸突，電壓閘控 Na⁺ 通道集中在此，動作電位在結與結之間跳躍。","n":"以 19 世紀法國病理學家 Louis-Antoine Ranvier 命名。","c":"7.1、7.2","w":"有髓鞘軸突上，相鄰兩段髓鞘之間約 1 μm 的裸露處。","f":"電壓閘控 Na⁺ 通道集中在蘭氏結，動作電位只在這裡產生，訊號從一個結跳到下一個結（跳躍式傳導）。","e":"多發性硬化症破壞中樞髓鞘，跳躍式傳導失效 → 神經訊號變慢或中斷。"},
"whitematter":{"t":"白質、灰質 white / gray matter","d":"<b>白質</b>：有髓鞘的軸突集中處，呈白色。<b>灰質</b>：神經元細胞本體與樹突集中處。","c":"7.1；第 8 章","f":"髓鞘含大量脂質而呈白色，所以白質是「傳輸線路」；灰質是神經元本體所在，負責「處理資訊」。大腦灰質在外（皮質），脊髓灰質在內（H 形）。","m":"<b>大腦外灰內白、脊髓外白內灰</b>。"},
"neurotroph":{"t":"神經營養因子 neurotrophins","d":"促進神經元生長、存活與突觸可塑性的蛋白質，如 NGF、BDNF。","c":"7.1","f":"由目標組織或膠細胞分泌，經逆向軸突運輸送回神經元本體，支持神經元存活、軸突生長與突觸的強化。","e":"BDNF 與學習記憶、運動對大腦的益處有關；NGF 由 Rita Levi-Montalcini 發現，1986 年獲諾貝爾獎。","m":"<b>神經元的肥料</b>。"},
"bbb":{"t":"血腦障壁 blood-brain barrier","d":"腦微血管內皮細胞以緊密連接相連、沒有開孔，加上星狀膠細胞誘導，限制血中物質進入腦；脂溶性物質可通過，葡萄糖靠 GLUT1。","c":"7.1；第 8 章","w":"腦部微血管壁。","f":"內皮細胞以<b>緊密連接</b>封住細胞間隙、沒有開孔，水溶性物質不能自由通過；脂溶性分子（O₂、CO₂、酒精、麻醉劑）可直接穿過；葡萄糖（GLUT1）、胺基酸靠專一的運輸蛋白進入。","e":"多巴胺不能通過血腦障壁，所以帕金森氏症用能通過的 L-多巴；下視丘、極後區等少數區域沒有障壁，才能偵測血中物質。","m":"<b>脂溶可過、水溶要門票</b>。"},
"graded":{"t":"分級電位 graded potential","d":"大小隨刺激強度而變、傳一段距離就衰減的膜電位變化，發生在樹突與細胞本體（如突觸後電位）。","c":"7.2","f":"刺激越強，電位變化越大；可以相加（加成），但隨距離衰減，所以只能傳很短的距離。包括突觸後電位、感受器電位、終板電位。","m":"<b>分級電位：可大可小、會衰減；動作電位：全有全無、不衰減</b>。"},
"ap":{"t":"動作電位 action potential","d":"膜電位達到閾值後，在約 1–2 毫秒內從 −70 衝到約 +30 mV 再回來的電訊號；全有全無、能不衰減地沿軸突傳導。","c":"7.2","f":"<b>去極化</b>：達閾值 → 電壓閘控 Na⁺ 通道打開 → Na⁺ 湧入 → 膜電位衝到正值。<b>再極化</b>：Na⁺ 通道失活、K⁺ 通道打開 → K⁺ 流出。<b>過極化</b>：K⁺ 通道關得慢，短暫比靜止還負。鈉鉀幫浦之後慢慢恢復離子濃度。","e":"每次動作電位移動的離子量非常少，所以濃度幾乎不變；神經能連續發射上百次。","m":"<b>Na⁺ 進來往上、K⁺ 出去往下</b>。"},
"vgc":{"t":"電壓閘控通道 voltage-gated channels","d":"依膜電位改變而打開或關閉的離子通道。電壓閘控 Na⁺ 通道快開快失活，K⁺ 通道慢開。","c":"7.2","f":"Na⁺ 通道有兩道門：活化門（快開）與失活門（稍後關閉），所以動作電位很短，並造成不反應期。K⁺ 通道開得慢、關得慢，負責再極化與後過極化。","e":"局部麻醉藥（lidocaine）阻斷電壓閘控 Na⁺ 通道；河豚毒素也是。","m":"<b>Na⁺ 快開快關、K⁺ 慢開慢關</b>。"},
"threshold":{"t":"閾值 threshold","d":"引發動作電位所需的最低去極化程度，神經元約 −55 mV。","n":"「閾」是門檻的意思。","c":"7.2","f":"去極化到閾值時，打開的 Na⁺ 通道帶進來的正電足以引發更多 Na⁺ 通道打開（正回饋），動作電位就一發不可收拾。","m":"<b>約 −55 mV＝扣下板機</b>。"},
"repol":{"t":"再極化 repolarization","d":"動作電位的「下坡」：膜電位從正值回到負值。","c":"7.2","f":"Na⁺ 通道失活停止進鈉，同時電壓閘控 K⁺ 通道打開讓 K⁺ 流出；K⁺ 通道關得慢，膜電位會短暫低於靜止值（後過極化）。","m":"<b>再極化靠 K⁺ 出去</b>。"},
"allnone":{"t":"全有全無定律 all-or-none law","d":"刺激未達閾值不產生動作電位；達到閾值就產生大小固定的動作電位，不會因刺激更強而變大。","c":"7.2","f":"刺激強度的資訊不是靠動作電位的「大小」，而是靠<b>頻率</b>（強刺激 → 發射更密）與<b>徵召</b>（更多神經纖維）傳遞。","m":"<b>大小固定，強度看頻率</b>。"},
"recruit":{"t":"徵召、大小原則 recruitment / size principle","d":"刺激越強，被活化的神經纖維（或運動單位）越多；徵召時依「大小原則」由小到大逐步加入。","c":"7.2；第 12 章","f":"不同神經纖維的閾值不同；弱刺激只活化閾值低的，強刺激連閾值高的也活化。在肌肉，<b>大小原則</b>：小的運動神經元（支配少量、慢縮、耐疲勞的肌纖維）閾值低，先被徵召；需要更大力量時，才徵召大的運動單位（快縮、力量大、易疲勞）。","e":"拿起羽毛只動用少數小運動單位；搬重物或衝刺時才大量徵召大運動單位（第 12 章）。","m":"<b>要更大力 → 叫更多人來，先小後大</b>。"},
"refract":{"t":"不反應期 refractory period","d":"<b>絕對</b>：Na⁺ 通道失活，再強的刺激也無法引發動作電位。<b>相對</b>：需要比平常更強的刺激。","c":"7.2；第 12、13 章","f":"<b>絕對不反應期</b>：Na⁺ 通道還在失活，無法再發射 → 確保動作電位單向前進、不會倒流，並限制最高發射頻率。<b>相對不反應期</b>：K⁺ 仍在外流、膜較負，需要更強的刺激。","m":"<b>絕對：門被鎖；相對：門很重</b>。"},
"salt":{"t":"跳躍式傳導 saltatory conduction","d":"有髓鞘軸突上，動作電位只在蘭氏結產生，從一個結「跳」到下一個結，傳得快又省能量。","n":"拉丁文 saltare＝跳躍。","c":"7.2","f":"髓鞘絕緣、電流在軸突內快速傳到下一個蘭氏結，只在結上重新產生動作電位，所以速度可達每秒 100 公尺以上，而且離子進出少、省能量。","m":"<b>跳著走：快又省</b>；軸突越粗、有髓鞘 → 越快。"},
"synapse":{"t":"突觸 synapse","d":"神經元和另一個細胞（神經、肌肉、腺體）傳遞訊號的連接處。","n":"1897 年 Sherrington 取希臘文「扣在一起」命名。","c":"7.3","f":"<b>化學性突觸</b>（最多）：突觸前釋放神經傳遞物質 → 擴散過突觸間隙 → 與突觸後受體結合；單向、可調節。<b>電性突觸</b>：以間隙連接讓離子直接通過，速度快，見於心肌、平滑肌與部分腦區。","m":"<b>化學突觸：電 → 化學 → 電</b>。"},
"nmj":{"t":"神經肌肉接合處 neuromuscular junction","d":"運動神經和骨骼肌接觸、傳遞命令的地方。","c":"7.4；第 12 章","f":"動作電位到達末梢 → Ca²⁺ 流入 → 釋放<b>乙醯膽鹼</b> → 結合運動終板上的<b>菸鹼型受體</b>（離子通道）→ 終板電位 → 肌纖維動作電位 → 收縮；乙醯膽鹼酯酶迅速分解 ACh 結束訊號。","e":"重症肌無力（受體被抗體破壞）、肉毒桿菌毒素（阻止 ACh 釋放）、箭毒（阻斷受體）都作用在這裡。","m":"<b>ACh → 菸鹼型 → 一定興奮</b>。"},
"svesicle":{"t":"突觸小泡 synaptic vesicles","d":"突觸前末梢內裝著神經傳遞物質的小囊泡，Ca²⁺ 進入時以胞吐方式釋放。","c":"7.3","f":"神經傳遞物質在末梢合成並裝進小泡；動作電位使電壓閘控 Ca²⁺ 通道打開 → Ca²⁺ 讓 SNARE 蛋白把小泡與細胞膜融合 → 胞吐。","e":"肉毒桿菌毒素切斷 SNARE 蛋白 → ACh 釋放不出來 → 肌肉麻痺；醫美除皺就是利用這點。","m":"<b>Ca²⁺ 一進、小泡就倒</b>。"},
"cleft":{"t":"突觸間隙 synaptic cleft","d":"突觸前後兩個細胞之間非常狹窄的縫隙，神經傳遞物質要「游」過去。","c":"7.3","f":"距離很短，擴散只需不到 1 毫秒；這也是化學性突觸延遲的來源之一。間隙中有分解酵素（如乙醯膽鹼酯酶）。"},
"epsp":{"t":"EPSP、IPSP 突觸後電位","d":"<b>EPSP</b>（興奮性突觸後電位）：去極化，使神經元較易達到閾值。<b>IPSP</b>（抑制性）：過極化，較難達到閾值。","c":"7.3、7.7","f":"EPSP：通常是 Na⁺（或陽離子）流入 → 去極化，例：麩胺酸、ACh（菸鹼型）。IPSP：Cl⁻ 流入或 K⁺ 流出 → 過極化，例：GABA、甘胺酸。兩者都是分級電位，在軸丘加總，決定是否發射動作電位。","m":"<b>E＝油門、I＝煞車</b>。"},
"reuptake":{"t":"再攝取 reuptake","d":"突觸前末梢把釋放出去的神經傳遞物質回收，終止訊號並重複利用。","e":"SSRI 抗憂鬱藥、古柯鹼阻斷再攝取。","c":"7.3、7.5","f":"突觸前末梢以運輸蛋白把神經傳遞物質（多巴胺、正腎上腺素、血清素、麩胺酸、GABA）收回，重新裝進小泡，或被 MAO 分解。","m":"<b>擋住回收 → 作用延長</b>（SSRI、古柯鹼）。"},
"ach":{"t":"乙醯膽鹼 acetylcholine（ACh）","d":"由膽鹼與乙醯輔酶 A 合成的神經傳遞物質：骨骼肌的運動神經、所有自主神經節前神經元、副交感節後神經元都釋放它。","c":"7.4；第 9、12 章","w":"①所有骨骼肌的運動神經；②交感與副交感的<b>節前</b>神經元；③副交感的<b>節後</b>神經元；④腦中參與學習記憶的路徑。","f":"由<b>膽鹼＋乙醯 CoA</b> 經膽鹼乙醯轉移酶合成；作用在菸鹼型（離子通道）或毒蕈鹼型（G 蛋白）受體；由乙醯膽鹼酯酶分解成乙酸與膽鹼，膽鹼被回收再用。","e":"阿茲海默症乙醯膽鹼神經元減少，常用乙醯膽鹼酯酶抑制劑治療。","m":"<b>ACh 原料：膽鹼＋乙醯 CoA</b>（營養素膽素、泛酸）。"},
"nicotinic":{"t":"菸鹼型受體 nicotinic receptor","d":"乙醯膽鹼的離子通道型受體（尼古丁也能活化），在骨骼肌與自主神經節，作用快、使細胞去極化。箭毒可阻斷。","c":"7.4；第 9 章","w":"骨骼肌運動終板、所有自主神經節、腎上腺髓質、腦。","f":"本身就是配體閘控離子通道：ACh 結合 → 通道打開讓 Na⁺ 進入（K⁺ 出）→ 去極化，作用快，永遠是興奮。","m":"<b>菸鹼型＝快、通道、興奮</b>。"},
"muscarinic":{"t":"毒蕈鹼型受體 muscarinic receptor","d":"乙醯膽鹼的 G 蛋白偶聯受體（毒菇中的毒蕈鹼也能活化），在副交感神經的標的器官，可興奮或抑制。阿托平可阻斷。","c":"7.4；第 9 章","w":"副交感神經節後的目標器官（心臟、腸胃、膀胱、腺體、瞳孔），以及交感神經支配的汗腺。","f":"G 蛋白偶聯受體，作用較慢，依次型可興奮或抑制：在心臟使心跳變慢（開 K⁺ 通道），在腸胃與腺體則促進收縮與分泌。","e":"阿托平阻斷它 → 心跳加快、口乾、瞳孔放大；毒菇中毒、有機磷中毒時它過度刺激 → 流涎、流淚、腹瀉。","m":"<b>毒蕈鹼型＝慢、G 蛋白、可興奮可抑制</b>。"},
"lgc":{"t":"配體閘控通道 ligand-gated channel","d":"化學物質（例如神經傳遞物質）一結合就打開的離子通道。","c":"7.4","f":"受體與通道是同一個蛋白質，所以反應非常快（毫秒級）。例：菸鹼型 ACh 受體（陽離子）、GABA<sub>A</sub> 受體與甘胺酸受體（Cl⁻）、麩胺酸的 AMPA 與 NMDA 受體。","m":"<b>配體＝鑰匙，一插就開</b>（G 蛋白偶聯受體則要經過第二傳訊者）。"},
"ache":{"t":"乙醯膽鹼酯酶 acetylcholinesterase（AChE）","d":"在突觸間隙把乙醯膽鹼分解成乙酸與膽鹼、終止訊號的酵素。","e":"<b>有機磷農藥</b>與神經毒氣抑制它 → ACh 堆積 → 流涎、流淚、腹瀉、瞳孔縮小、肌肉抽搐後麻痺；用阿托平與解磷定解毒。治療重症肌無力與阿茲海默症則刻意使用可逆性抑制劑。","c":"7.4","f":"每秒可分解上萬個 ACh 分子，讓突觸訊號又短又精準；分解出的膽鹼被突觸前末梢回收再合成 ACh。","m":"<b>擋住酯酶 → ACh 停不下來</b>。"},
"choline":{"t":"膽素（膽鹼）choline","d":"製造<b>細胞膜（卵磷脂）</b>、神經傳導物質<b>乙醯膽鹼</b>，並提供<b>甲基</b>的營養素；身體能自己合成一部分，但不夠用。","c":"7.4；營養學","tag":"營養素","nu":"<b>來源</b>：蛋黃（最豐富）、肝臟、肉類、魚、黃豆、十字花科蔬菜。<br><b>建議量</b>（國人 DRIs 第八版，足夠攝取量）：成人男 450、女 390 mg；懷孕 ＋20、哺乳 ＋140；上限攝取量 3,500 mg。<br><b>過量</b>：身體散發魚腥味、低血壓、流汗。","ch":"帶正電的四級銨化合物（三個甲基接在氮上），含三個可提供的甲基。","bc":"①<b>磷脂醯膽鹼（卵磷脂）</b>：細胞膜的主要磷脂質；也是肝臟組裝並送出 VLDL 所必需。<br>②<b>乙醯膽鹼</b>：膽鹼＋乙醯 CoA →（膽鹼乙醯轉移酶）→ 乙醯膽鹼。<br>③氧化成<b>甜菜鹼</b>，把甲基交給同半胱胺酸 → 甲硫胺酸（不需要 B12 的另一條路）。<br>肝臟也能用磷脂醯乙醇胺接上 SAM 的甲基自己合成（PEMT），雌激素促進這條路。","mb":"作為甲基供應者，與葉酸、B12、甲硫胺酸一起維持 SAM，影響 DNA 甲基化；懷孕期胎兒腦部發育的需要量大。","ph":"神經肌肉接合處與副交感神經的乙醯膽鹼（第 7、9 章）；細胞膜構造（第 3、6 章）；肝臟脂質輸出（第 19 章）。","dt":"<b>長期全靜脈營養</b>：缺乏時肝臟送不出 VLDL → <b>脂肪肝</b>、肝指數上升。<br><b>懷孕與哺乳</b>：需要量增加。<br>停經後女性自行合成較少，較容易不足。","m":"<b>膽素三用途：做膜、做乙醯膽鹼、給甲基</b>；最好的來源是<b>蛋黃</b>。","ex":"缺乏的典型表現是<b>脂肪肝</b>（VLDL 無法送出）與肌肉損傷；嚴格說不是維生素，但已訂有足夠攝取量。"},
"atropine":{"t":"阿托平 atropine","d":"阻斷毒蕈鹼型受體的藥物：使瞳孔放大、心跳加快、口乾；用來治療有機磷中毒。","n":"來自顛茄（Atropa belladonna）。","c":"7.4；第 9 章","f":"和 ACh 競爭毒蕈鹼型受體但不活化它，阻斷副交感作用：瞳孔放大、心跳加快、唾液與支氣管分泌減少、腸胃蠕動變慢。","e":"眼科散瞳、心跳過慢急救、有機磷中毒解毒、手術前減少分泌。","m":"<b>阿托平＝副交感關掉</b>：乾、熱、紅、快、瞳孔大。"},
"curare":{"t":"箭毒 curare","d":"阻斷骨骼肌菸鹼型受體的毒素，使骨骼肌（包括呼吸肌）麻痺；南美原住民塗在箭上狩獵。手術用的肌肉鬆弛劑原理類似。","c":"7.4","f":"競爭性阻斷骨骼肌運動終板的菸鹼型受體 → ACh 無法引起終板電位 → 骨骼肌鬆弛麻痺；不影響心肌與平滑肌。","e":"手術麻醉時使用類似藥物讓肌肉放鬆，需同時人工呼吸；可用乙醯膽鹼酯酶抑制劑逆轉。","m":"<b>箭毒擋菸鹼型（肌肉）、阿托平擋毒蕈鹼型（內臟）</b>。"},
"mg":{"t":"重症肌無力 myasthenia gravis","d":"自體免疫疾病：抗體破壞骨骼肌的乙醯膽鹼菸鹼型受體，肌肉容易疲勞無力（眼瞼下垂常見）；用可逆的 AChE 抑制劑治療。","c":"7.4；第 12 章","f":"自體抗體攻擊運動終板的 ACh 菸鹼型受體 → 受體減少 → 反覆使用時終板電位不足 → 肌肉越用越無力，休息後改善。常先影響眼肌（眼瞼下垂、複視）、吞嚥與咀嚼肌。","e":"用可逆性乙醯膽鹼酯酶抑制劑（pyridostigmine）讓 ACh 留久一點；吞嚥困難時需調整食物質地，並把進食安排在藥效好的時段。","n":"myasthenia gravis：希臘文「肌肉無力」＋拉丁文「嚴重的」。","m":"<b>越用越無力、休息會好</b>。"},
"endplate":{"t":"運動終板 motor end plate","d":"骨骼肌細胞膜上接受運動神經末梢的特化區域，有大量菸鹼型受體；產生的去極化叫終板電位。","c":"7.4；第 12 章","w":"骨骼肌纖維上正對運動神經末梢的部位，膜摺成許多皺褶增加受體數量。","f":"ACh 打開菸鹼型受體 → 終板電位（分級電位，但通常大到一定能引發肌纖維的動作電位，所以神經肌肉傳遞非常可靠）。","m":"<b>終板電位一定夠大</b>（一對一傳遞）。"},
"monoamine":{"t":"單胺類 monoamines","d":"由單一胺基酸改造而來、帶一個胺基的神經傳導物質家族。","c":"7.5","f":"兒茶酚胺（多巴胺、正腎上腺素、腎上腺素，來自酪胺酸）、血清素（來自色胺酸）、組織胺（來自組胺酸）。合成需要 B6（去羧酶）；由 MAO 與 COMT 分解，或被再攝取回收。","e":"許多抗憂鬱藥作用在單胺系統（SSRI、MAO 抑制劑）。","m":"<b>酪 → 兒茶酚胺、色 → 血清素、組 → 組織胺</b>。"},
"catechol":{"t":"兒茶酚胺 catecholamines","d":"由<b>酪胺酸</b>合成的一群單胺：<b>多巴胺、正腎上腺素、腎上腺素</b>。","c":"7.5；第 9、11 章","f":"合成路徑：<b>酪胺酸</b> →（酪胺酸羥化酶，速率限制，需鐵與四氫生物喋呤）→ L-多巴 →（去羧，需 B6）→ <b>多巴胺</b> →（多巴胺 β-羥化酶，需銅與維生素 C）→ <b>正腎上腺素</b> →（甲基轉移，SAM，皮質醇誘導）→ <b>腎上腺素</b>。","m":"<b>酪 → 多巴 → 多巴胺 → 正腎 → 腎</b>；營養素：鐵、B6、銅、C、SAM。"},
"serotonin":{"t":"血清素 serotonin（5-HT）","d":"由<b>色胺酸</b>合成的神經傳遞物質，調節情緒、睡眠、食慾、體溫；約 90% 在腸道。","n":"最早在血清（serum）中發現能收縮血管（tonic）而得名。","c":"7.5","f":"色胺酸 →（色胺酸羥化酶）→ 5-羥色胺酸 →（去羧，需 B6）→ 血清素；在松果體再轉成褪黑激素。腦中血清素調節情緒、睡眠、食慾；腸道的血清素調節蠕動；血小板也攜帶血清素。","e":"SSRI 抗憂鬱藥阻止它回收；類癌腫瘤大量製造血清素 → 潮紅、腹瀉，並消耗色胺酸造成菸鹼素缺乏。","m":"<b>色胺酸 → 血清素 → 褪黑激素</b>。"},
"dopamine":{"t":"多巴胺 dopamine","d":"由酪胺酸 → L-多巴合成的兒茶酚胺：黑質紋狀體路徑控制運動（缺乏 → 帕金森氏症），中腦邊緣路徑與獎賞、成癮有關。","c":"7.5；第 8 章","f":"由腦中三大路徑發揮作用：<b>黑質紋狀體</b>（運動控制）、<b>中腦邊緣</b>（獎賞與動機）、<b>結節漏斗</b>（抑制泌乳素）。","e":"缺乏黑質多巴胺 → 帕金森氏症；中腦邊緣路徑過度活躍與思覺失調症有關；成癮藥物增加這條路徑的多巴胺。","m":"<b>多巴胺：動作、獎賞、壓泌乳素</b>。"},
"ne":{"t":"正腎上腺素 norepinephrine","d":"交感神經節後神經元的神經傳遞物質；在腦中由藍斑核釋放，與清醒、警覺有關；也是腎上腺髓質分泌的激素之一。","c":"7.5；第 9 章","f":"作用在 α 與 β 腎上腺素受體：血管收縮（α₁）、心跳加快與收縮力增強（β₁）等。由再攝取回收，或被 MAO 與 COMT 分解。","m":"<b>交感節後＝正腎上腺素</b>（汗腺例外，用 ACh）。"},
"epi2":{"t":"腎上腺素 epinephrine（adrenaline）","d":"主要由腎上腺髓質分泌的兒茶酚胺激素，參與「戰或逃」反應：心跳加快、血糖上升。","c":"第 9、11 章","w":"由<b>腎上腺髓質</b>分泌（約 80% 是腎上腺素、20% 正腎上腺素）。","f":"作用：心跳加快、支氣管擴張（β₂）、肝醣分解與糖質新生（升血糖）、脂肪分解、血液重新分配到肌肉。","e":"過敏性休克急救用腎上腺素筆；嗜鉻細胞瘤分泌過多 → 陣發性高血壓、心悸、冒汗。","m":"<b>腎上腺素＝全身動員</b>。"},
"mao":{"t":"單胺氧化酶 monoamine oxidase（MAO）","d":"分解單胺類（血清素、多巴胺、正腎上腺素、酪胺）的酵素；MAO 抑制劑是一類抗憂鬱藥。","c":"7.5","w":"粒線體外膜，存在神經末梢、腸道、肝臟。","f":"把單胺類氧化去胺而失活。腸道與肝臟的 MAO 會先分解食物中的酪胺，阻止它進入循環。","e":"服用 MAO 抑制劑的病人，若吃大量含酪胺的熟成起司、醃漬物、紅酒 → 酪胺大量釋放正腎上腺素 → 高血壓危象。","m":"<b>MAO 抑制劑＋酪胺＝血壓爆衝</b>。"},
"tyramine":{"t":"酪胺 tyramine","d":"由酪胺酸去羧產生的胺類，存在發酵、熟成、醃漬的食物中，會讓神經末梢釋放正腎上腺素。","c":"7.5；膳食療養","e":"服用 MAO 抑制劑者要限制：熟成起司、醃漬或煙燻魚肉、發酵豆製品（醬油、味噌大量時）、紅酒與啤酒、過熟的香蕉與酪梨。","m":"<b>酪胺 ≠ 酪胺酸</b>；酪胺是熟成食物的副產物。"},
"ldopa":{"t":"L-多巴 L-dopa","d":"多巴胺的前驅物，可經胺基酸載體通過血腦障壁，在腦中轉成多巴胺；用來治療帕金森氏症。","c":"7.1、7.5","f":"多巴胺本身無法通過血腦障壁，L-多巴可以經大型中性胺基酸載體進入腦，再由去羧酶轉成多巴胺。常和周邊去羧酶抑制劑（carbidopa）合用，減少在腦外就被轉換。","e":"高蛋白餐中的大量中性胺基酸會和 L-多巴競爭載體，所以有些病人需調整蛋白質的分配時間（例如白天低蛋白、晚上再補足）。","m":"<b>多巴胺進不去，L-多巴可以</b>。"},
"ssri":{"t":"選擇性血清素再攝取抑制劑 SSRI","d":"阻止血清素被突觸前末梢回收，延長其作用的抗憂鬱藥，如百憂解。","c":"7.5","f":"抑制突觸前的血清素運輸蛋白 → 血清素在突觸間隙停留較久 → 作用增強。臨床效果通常要數週才出現，與受體的適應性改變有關。","e":"常見藥物：fluoxetine（百憂解）、sertraline；副作用可能有腸胃不適、食慾改變。","m":"<b>擋回收 → 血清素留久一點</b>。"},
"parkinson":{"t":"帕金森氏症 Parkinson's disease","d":"中腦黑質的多巴胺神經元退化，造成靜止型顫抖、僵硬、動作遲緩；以 L-多巴治療。","c":"7.5；第 8 章","f":"黑質緻密部多巴胺神經元退化 → 紋狀體多巴胺不足 → 基底核對運動的調控失衡。神經元中常可見 α-突觸核蛋白聚集的路易氏體。","e":"症狀：靜止型顫抖、肌肉僵硬、動作遲緩、姿勢不穩。營養問題：吞嚥困難、便秘、體重下降，以及蛋白質與 L-多巴的交互作用。","n":"1817 年英國醫師 James Parkinson 首先描述「震顫麻痺」。","m":"<b>顫、僵、慢、不穩</b>。"},
"gaba":{"t":"GABA γ-胺基丁酸","d":"腦中最主要的<b>抑制性</b>神經傳遞物質，打開 Cl⁻ 通道使神經元過極化；由麩胺酸脫羧而成（需維生素 B6）。苯二氮平、酒精增強其作用。","c":"7.6","f":"由<b>麩胺酸</b>經麩胺酸去羧酶（需 <b>B6</b>）合成。GABA<sub>A</sub> 受體是 Cl⁻ 通道 → Cl⁻ 流入 → 過極化（IPSP）；GABA<sub>B</sub> 是 G 蛋白偶聯受體。","e":"苯二氮平類安眠鎮靜藥、巴比妥類、酒精都增強 GABA<sub>A</sub> 作用；嬰兒缺 B6 → GABA 不足 → 抽搐。","m":"<b>麩胺酸（油門）去羧 → GABA（煞車）</b>，需要 B6。"},
"glycine2":{"t":"甘胺酸 glycine（神經傳遞物質）","d":"脊髓與腦幹主要的抑制性神經傳遞物質，打開 Cl⁻ 通道；番木鱉鹼阻斷其受體造成痙攣。","c":"7.6","f":"作用在甘胺酸受體（Cl⁻ 通道）→ 過極化，抑制脊髓運動神經元，避免肌肉過度收縮。","e":"番木鱉鹼（士的寧）阻斷甘胺酸受體 → 全身肌肉強直痙攣；破傷風毒素阻止甘胺酸與 GABA 釋放 → 牙關緊閉、角弓反張。","m":"<b>脊髓的煞車是甘胺酸</b>。"},
"excito":{"t":"興奮毒性 excitotoxicity","d":"神經元被過多的麩胺酸「刺激到死」。","c":"7.6","f":"缺血缺氧 → ATP 不足 → 麩胺酸無法回收而堆積 → 過度活化 NMDA 受體 → 大量 Ca²⁺ 湧入 → 活化蛋白酶、脂酶、產生自由基 → 神經元死亡。","e":"中風、腦外傷、癲癇重積狀態的神經損傷，部分與興奮毒性有關。","m":"<b>麩胺酸太多 → 鈣湧入 → 細胞死</b>。"},
"nmda":{"t":"NMDA、AMPA 受體","d":"兩種麩胺酸離子通道型受體。<b>AMPA</b> 讓 Na⁺ 進入產生 EPSP；<b>NMDA</b> 在去極化時才開，讓 Ca²⁺ 進入，觸發長期增益（LTP）。","c":"7.6、7.7","f":"<b>AMPA</b>：麩胺酸一結合就讓 Na⁺ 進入 → 快速 EPSP。<b>NMDA</b>：需要麩胺酸＋膜已去極化（把堵住通道的 Mg²⁺ 推開）才打開，讓 Ca²⁺ 進入 → 啟動長期增益（學習記憶）；過度活化則造成興奮毒性。","m":"<b>NMDA＝雙重條件才開的「巧合偵測器」</b>，Mg²⁺ 是門栓。"},
"substp":{"t":"P 物質 substance P","d":"痛覺感覺神經在脊髓釋放、傳遞痛覺的胜肽神經傳遞物質。","c":"7.6；第 10 章","f":"由 11 個胺基酸組成；痛覺纖維在脊髓背角釋放，傳遞痛覺，也在周邊引起血管擴張與發炎（神經性發炎）。","e":"辣椒素先刺激再耗竭痛覺纖維中的 P 物質，所以辣椒素藥膏可用來止痛；內生性鴉片抑制 P 物質釋放。","m":"<b>P＝Pain</b>（便於記，名稱原意是 Powder）。"},
"opioid":{"t":"內生性鴉片 endogenous opioids","d":"身體自己製造、作用在鴉片受體的胜肽：β-腦內啡、腦啡肽、強啡肽；能止痛、產生愉悅感。","e":"運動後的「跑者高潮」。納洛酮可阻斷鴉片受體。","c":"7.6、7.7；第 10 章","f":"作用在 μ、δ、κ 鴉片受體（G 蛋白偶聯受體），抑制痛覺傳遞（減少 P 物質釋放）並活化獎賞路徑。","m":"<b>腦內的天然止痛藥</b>：腦內啡、腦啡肽、強啡肽。"},
"npy":{"t":"神經胜肽 Y neuropeptide Y（NPY）","d":"下視丘中強力<b>促進食慾</b>的神經胜肽。","c":"7.6；第 19 章","w":"下視丘弓狀核的神經元（也在交感神經中與正腎上腺素共同釋放）。","f":"飢餓訊號（飢餓素↑、瘦體素↓）→ NPY／AgRP 神經元活化 → 食慾增加、能量消耗減少。瘦體素抑制這群神經元。","m":"<b>NPY＝「Now Please Yum」吃吧</b>。"},
"endocann":{"t":"內生性大麻素 endocannabinoids","d":"由突觸後神經元合成、逆向作用在突觸前末梢以減少傳遞物質釋放的脂質訊號（anandamide、2-AG）；參與食慾、痛覺、記憶。","c":"7.6","f":"突觸後神經元在需要時才合成（不儲存在小泡），反方向擴散到突觸前末梢的 CB1 受體 → 減少神經傳遞物質釋放；參與食慾、痛覺、情緒與記憶。","e":"大麻中的 THC 作用在同一受體，所以會增加食慾（「嘴饞」）。","m":"<b>逆向傳話：叫突觸前少放一點</b>。"},
"no":{"t":"一氧化氮 nitric oxide（NO）","d":"由精胺酸產生的氣體訊號分子，直接擴散進鄰近細胞產生 cGMP，使平滑肌放鬆（血管擴張、勃起）。","c":"7.6；第 14 章","f":"一氧化氮合成酶把<b>精胺酸</b>變成 NO＋瓜胺酸；NO 是氣體，直接穿過細胞膜 → 活化鳥苷酸環化酶 → <b>cGMP</b>↑ → 平滑肌放鬆。內皮細胞產生的 NO 讓血管擴張。","e":"硝化甘油在體內釋放 NO 治療心絞痛；威而鋼抑制分解 cGMP 的 PDE5，延長 NO 的作用。","m":"<b>精胺酸 → NO → cGMP → 放鬆</b>。"},
"adenosine":{"t":"腺苷 adenosine","d":"ATP 分解產物；在腦中隨清醒時間累積而促進睡意。咖啡因就是阻斷腺苷受體而提神。","c":"7.6","f":"清醒時腦中能量消耗，ATP 分解產生腺苷並逐漸累積 → 作用在腺苷受體 → 抑制促醒神經元 → 想睡；睡眠時腺苷被清除。腺苷也使血管擴張、心跳變慢。","e":"咖啡因、茶鹼是腺苷受體拮抗劑，所以能提神；急診也用腺苷靜脈注射終止某些心律不整。","m":"<b>腺苷累積＝睡意，咖啡因擋腺苷</b>。"},
"cotrans":{"t":"共同傳遞物質 cotransmitter","d":"神經末梢同時釋放的「第二種」傳遞物質，用來調整主要訊號的效果。","c":"7.6","f":"小分子傳遞物質常與神經胜肽或 ATP 共同釋放，產生快、慢不同的作用，增加神經訊號的變化。","e":"交感神經同時釋放正腎上腺素、ATP 與神經胜肽 Y。","m":"<b>主唱＋和聲</b>。"},
"spatial":{"t":"空間加成、時間加成 spatial / temporal summation","d":"神經元把收到的多個突觸後電位「加起來」，總和夠大才發射動作電位；分成同時不同處（空間）與同處連續（時間）兩種。","c":"7.7；第 12 章","f":"單一 EPSP 通常太小，必須加成才能到閾值；IPSP 會抵銷 EPSP。這是神經元整合資訊的基本方式。","m":"<b>空間＝很多人同時喊；時間＝一個人連續喊</b>。"},
"diverg":{"t":"發散、會聚 divergence / convergence","d":"<b>發散</b>：一個神經元影響許多神經元。<b>會聚</b>：許多神經元的訊號集中到一個神經元。","c":"7.7；第 10 章","f":"發散讓一個訊號同時影響很多目標（例如一個運動神經元的訊號被傳到許多肌纖維）；會聚讓一個神經元整合許多來源，並決定是否發射（例如視網膜許多桿細胞會聚到一個神經節細胞，提高暗處敏感度）。","m":"<b>發散＝一對多、會聚＝多對一</b>。"},
"plastic":{"t":"突觸可塑性 synaptic plasticity","d":"突觸會依使用的情形變強或變弱，大腦因此能學習和記憶。","c":"7.7；第 8 章","f":"機制包括：受體數目改變（插入或移除 AMPA 受體）、傳遞物質釋放量改變、新突觸的形成與修剪；需要 Ca²⁺、蛋白質激酶與基因表現。","m":"<b>用進廢退</b>。"},
"ltp":{"t":"長期增益、長期抑制 LTP / LTD","d":"<b>LTP</b>：反覆高頻刺激使突觸長期變強（NMDA → Ca²⁺ → 插入 AMPA）。<b>LTD</b>：低頻刺激使突觸長期變弱（移除 AMPA）。","c":"7.7；第 8 章","f":"LTP：高頻刺激 → 突觸後去極化移開 NMDA 的 Mg²⁺ → Ca²⁺ 大量進入 → 活化 CaMKII → 插入更多 AMPA 受體 → 同樣的刺激產生更大的 EPSP。長期維持需要新蛋白質合成。LTD：低頻刺激、少量 Ca²⁺ → 移除 AMPA 受體 → 突觸變弱。","m":"<b>大量鈣 → 增強；少量鈣 → 減弱</b>。"},
"hippo":{"t":"海馬迴 hippocampus","d":"大腦顳葉內側的構造，負責把短期記憶轉成長期記憶；LTP 最早在這裡發現。","n":"形狀像海馬。","c":"第 8 章","w":"大腦顳葉內側，彎曲如海馬，屬於邊緣系統。","f":"把新的陳述性記憶（事件、事實）鞏固成長期記憶，並負責空間記憶；本身不是長期記憶的儲存處。","e":"阿茲海默症早期海馬迴就萎縮，所以先忘記最近的事；著名的 H.M. 病人切除雙側海馬迴後無法形成新的長期記憶。","m":"<b>海馬迴＝記憶的存檔鍵</b>。"},
"preinh":{"t":"突觸前抑制、突觸後抑制","d":"抑制可以作用在「接收端」（突觸後抑制）或「發送端」（突觸前抑制）。","c":"7.7","f":"突觸後抑制：GABA、甘胺酸使突觸後神經元過極化，所有輸入一起打折。突觸前抑制：抑制性神經元作用在另一個神經元的末梢，減少它的傳遞物質釋放，只針對特定輸入（例如內生性鴉片減少痛覺纖維釋放 P 物質）。","m":"<b>突觸後＝全面降音量；突觸前＝只關一支麥克風</b>。"}});
Object.assign(GL_ALIAS,{"中樞神經系統":"cns","CNS":"cns","周邊神經系統":"pns","PNS":"pns","體神經系統":"somatic","體神經":"somatic","自主神經系統":"autonomic","自主神經":"autonomic","神經節":"ganglion","尼氏小體":"nissl","軸丘":"hillock","軸突運輸":"axtrans","順向運輸":"axtrans","逆向運輸":"axtrans","感覺神經元":"sensoryn","傳入神經元":"sensoryn","運動神經元":"motorn","傳出神經元":"motorn","聯絡神經元":"intern","中間神經元":"intern","膠細胞":"neuroglia2","衛星細胞":"satellite","星狀膠細胞":"astro","微膠細胞":"microglia","室管膜細胞":"ependymal","神經膜":"neurilemma","蘭氏結":"ranvier","白質":"whitematter","灰質":"whitematter","神經營養因子":"neurotroph","血腦障壁":"bbb","分級電位":"graded","動作電位":"ap","電壓閘控":"vgc","閾值":"threshold","再極化":"repol","全有全無":"allnone","全有全無定律":"allnone","徵召":"recruit","不反應期":"refract","絕對不反應期":"refract","相對不反應期":"refract","跳躍式傳導":"salt","突觸":"synapse","神經肌肉接合處":"nmj","突觸小泡":"svesicle","突觸間隙":"cleft","EPSP":"epsp","IPSP":"epsp","再攝取":"reuptake","乙醯膽鹼":"ach","ACh":"ach","菸鹼型":"nicotinic","毒蕈鹼型":"muscarinic","配體閘控":"lgc","乙醯膽鹼酯酶":"ache","AChE":"ache","膽鹼":"choline","阿托平":"atropine","箭毒":"curare","重症肌無力":"mg","運動終板":"endplate","終板電位":"endplate","單胺類":"monoamine","兒茶酚胺":"catechol","血清素":"serotonin","多巴胺":"dopamine","正腎上腺素":"ne","腎上腺素":"epi2","單胺氧化酶":"mao","MAO":"mao","酪胺":"tyramine","L-多巴":"ldopa","SSRI":"ssri","帕金森氏症":"parkinson","GABA":"gaba","興奮毒性":"excito","NMDA":"nmda","AMPA":"nmda","P 物質":"substp","內生性鴉片":"opioid","腦內啡":"opioid","腦啡肽":"opioid","神經胜肽 Y":"npy","NPY":"npy","內生性大麻素":"endocann","一氧化氮":"no","NO":"no","腺苷":"adenosine","共同傳遞物質":"cotrans","空間加成":"spatial","時間加成":"spatial","發散":"diverg","會聚":"diverg","突觸可塑性":"plastic","長期增益":"ltp","長期抑制":"ltp","LTP":"ltp","LTD":"ltp","海馬迴":"hippo","突觸前抑制":"preinh","突觸後抑制":"preinh"});

