Object.assign(GL,{"nephron":{"t":"腎元 nephron","d":"腎臟的功能單位，每腎約 100 萬個：腎小體（腎絲球＋鮑氏囊）→ 近曲小管 → 亨利氏環 → 遠曲小管，再接集尿管。","c":"17.1"},
"renalcorp":{"t":"腎小體 renal corpuscle","d":"腎絲球（一團微血管）與包住它的鮑氏囊；血漿在這裡被過濾成濾液。","c":"17.1"},
"glomerulus":{"t":"腎絲球、鮑氏囊","d":"<b>腎絲球</b>：入球與出球小動脈之間的一團高壓微血管。<b>鮑氏囊</b>（腎絲球囊）：杯狀包住腎絲球、收集濾液。","c":"17.1、17.2"},
"pct":{"t":"近曲小管 proximal convoluted tubule","d":"緊接腎小體、有刷狀緣的彎曲小管；再吸收約 65% 的 Na⁺ 與水、全部葡萄糖與胺基酸、大部分 HCO₃⁻；濾液仍等張。","c":"17.1、17.3"},
"henle":{"t":"亨利氏環 loop of Henle","d":"深入髓質的 U 形管：下行枝對水通透、上行枝主動打出 NaCl 而水不通透，形成逆流倍增。","c":"17.1、17.3"},
"dct":{"t":"遠曲小管 distal convoluted tubule","d":"回到皮質的小管段，起始處有緻密斑；噻嗪類利尿劑作用處，後段受醛固酮影響。","c":"17.1"},
"cd":{"t":"集尿管 collecting duct","d":"多個腎元共用、穿過髓質的管道；受 ADH（水通道蛋白-2）與醛固酮（Na⁺/K⁺）精細調節，決定尿的濃度與成分。","c":"17.1、17.3、17.5"},
"juxtamed":{"t":"皮質腎元、近髓質腎元","d":"<b>皮質腎元</b>（約 85%）：亨利氏環短。<b>近髓質腎元</b>（約 15%）：亨利氏環長、深入內髓質，負責濃縮尿液。","c":"17.1"},
"afferent":{"t":"入球小動脈、出球小動脈","d":"<b>入球</b>：把血送進腎絲球，交感與自動調節控制其口徑（決定 GFR）。<b>出球</b>：把血帶出腎絲球（不是靜脈），再形成管周微血管。","c":"17.1、17.2"},
"peritubular":{"t":"管周微血管、直血管","d":"出球小動脈之後的第二套微血管：<b>管周微血管</b>圍繞腎小管，接收再吸收的物質；<b>直血管</b>沿亨利氏環深入髓質，以逆流交換維持梯度。","c":"17.1、17.3"},
"micturition":{"t":"排尿反射 micturition reflex","d":"膀胱充盈 → 伸張受器 → 薦髓中樞 → 副交感使逼尿肌收縮、內括約肌放鬆；大腦與橋腦控制是否允許，並隨意控制外括約肌（陰部神經）。","c":"17.1（國考）"},
"detrusor":{"t":"逼尿肌、尿道括約肌","d":"<b>逼尿肌</b>：膀胱壁平滑肌，副交感使其收縮。<b>內括約肌</b>：平滑肌，不隨意。<b>外括約肌</b>：骨骼肌，隨意控制。","c":"17.1"},
"podocyte":{"t":"足細胞 podocytes","d":"鮑氏囊內層的細胞，伸出足突包住腎絲球微血管，足突間的過濾縫隙是過濾膜的最後一層。","c":"17.2"},
"filtmembrane":{"t":"腎絲球過濾膜","d":"三層：有窗孔的內皮（擋血球）、帶負電的基底膜（擋蛋白）、足細胞過濾縫隙；水與小分子可通過，白蛋白不能。","c":"17.2"},
"gfr":{"t":"腎絲球過濾率 GFR","d":"每分鐘兩腎濾出的液體量，約 125 mL/分（180 L/天）；評估腎功能最重要的指標，臨床以 eGFR 估算。","c":"17.2、17.4"},
"netfilt":{"t":"淨過濾壓 net filtration pressure","d":"腎絲球微血管靜水壓（約 60）－鮑氏囊靜水壓（約 15）－血漿膠體滲透壓（約 30）≈ 10–15 mmHg。","c":"17.2"},
"tgf":{"t":"腎小管腎絲球回饋 tubuloglomerular feedback","d":"緻密斑偵測流過遠端小管的 NaCl；GFR 太高時使入球小動脈收縮，把 GFR 降回來；自動調節機制之一。","c":"17.2"},
"maculadensa":{"t":"緻密斑、近腎絲球器","d":"<b>緻密斑</b>：遠曲小管起始處偵測 NaCl 的細胞。與入球小動脈的近腎絲球細胞（分泌腎素）合稱<b>近腎絲球器</b>。","c":"17.2、17.5"},
"proteinuria":{"t":"蛋白尿 proteinuria","d":"尿中出現蛋白質（特別是白蛋白），表示腎絲球過濾膜受損；尿白蛋白／肌酸酐比值（UACR）是糖尿病腎病變的早期指標。","c":"17.2、17.6"},
"countercurrent":{"t":"逆流倍增系統 countercurrent multiplier","d":"亨利氏環下行枝（水出）與上行枝（NaCl 主動出、水不出）液體流向相反，層層疊加，使髓質滲透壓從 300 增加到約 1,200 mOsm。","c":"17.3"},
"ccexchange":{"t":"逆流交換 countercurrent exchange","d":"直血管下行時吸鹽失水、上行時放鹽吸水，使血流不會沖走髓質的濃度梯度。","c":"17.3"},
"nkcc2":{"t":"Na⁺–K⁺–2Cl⁻ 共同運輸器 NKCC2","d":"亨利氏環粗上行枝管腔側的運輸蛋白，把 NaCl 移出小管液；環利尿劑抑制它。","c":"17.3、17.6"},
"aqp2":{"t":"水通道蛋白-2 aquaporin-2","d":"集尿管主細胞中受 ADH 控制的水通道：ADH → V2 受體 → cAMP → 插入管腔側膜，讓水被髓質吸出。","c":"17.3"},
"obligatory":{"t":"必然性、兼性再吸收","d":"<b>必然性</b>（約 85%）：近曲小管與下行枝，不受控制。<b>兼性</b>（約 15%）：集尿管，由 ADH 決定，決定尿量差異。","c":"17.3"},
"clearance":{"t":"清除率 renal plasma clearance","d":"每分鐘被腎臟完全清除某物質的血漿量＝尿中濃度 × 尿流量 ÷ 血漿濃度；&lt; GFR 表示再吸收，&gt; GFR 表示分泌。","c":"17.4"},
"inulin":{"t":"菊糖 inulin","d":"植物來源的果糖聚合物，只被過濾、不被再吸收或分泌，其清除率＝GFR，是測量 GFR 的標準方法（注意不是胰島素 insulin）。","c":"17.4"},
"creatinine":{"t":"肌酸酐 creatinine","d":"肌肉中肌酸與磷酸肌酸分解的產物，產量穩定、主要靠過濾排出；血清肌酸酐（正常約 0.6–1.2 mg/dL）用來估算 eGFR；肌肉量少者偏低。","c":"17.4"},
"egfr":{"t":"估計腎絲球過濾率 eGFR","d":"以血清肌酸酐、年齡、性別代入公式估算的 GFR；慢性腎臟病依它分 1–5 期。","c":"17.4、17.6"},
"bun":{"t":"血中尿素氮 BUN","d":"血中尿素的氮含量（約 7–20 mg/dL）；腎功能差時上升，但也受高蛋白飲食、脫水、腸胃出血影響，較不專一。","c":"17.4（國考）"},
"pah":{"t":"對胺基馬尿酸 PAH","d":"經過腎臟一次幾乎被過濾與分泌完全清除的物質，其清除率≈腎血漿流量（約 625 mL/分）。","c":"17.4"},
"glycosuria":{"t":"糖尿 glycosuria","d":"尿中出現葡萄糖；血糖超過腎閾值（約 180 mg/dL）或服用 SGLT2 抑制劑時發生，並引起滲透性利尿。","c":"17.4（國考）"},
"sglt2i":{"t":"SGLT2 抑制劑","d":"阻斷近曲小管葡萄糖再吸收的降血糖藥，讓多餘的葡萄糖從尿排出；需注意脫水與泌尿道感染。","c":"17.4"},
"enac":{"t":"上皮鈉通道 ENaC","d":"集尿管主細胞管腔側的 Na⁺ 通道，醛固酮增加其數量；amiloride 阻斷它。","c":"17.5"},
"principal":{"t":"主細胞、間插細胞","d":"集尿管的兩種細胞：<b>主細胞</b>受醛固酮（Na⁺ 再吸收、K⁺ 分泌）與 ADH（水通道）調節；<b>間插細胞</b>分泌 H⁺ 或 HCO₃⁻，調節酸鹼。","c":"17.5"},
"hyperkalemia":{"t":"高血鉀、低血鉀","d":"血鉀正常約 3.5–5.0 mEq/L。<b>高血鉀</b>（腎衰竭、醛固酮不足、酸中毒、保鉀藥物）與<b>低血鉀</b>（嘔吐腹瀉、利尿劑、醛固酮過多、鹼中毒）都可能致命的心律不整。","c":"17.5"},
"titratable":{"t":"可滴定酸 titratable acid","d":"尿中被磷酸鹽緩衝的 H⁺（HPO₄²⁻＋H⁺ → H₂PO₄⁻）。","c":"17.5"},
"loopdiuretic":{"t":"環利尿劑 loop diuretics","d":"如 furosemide，抑制亨利氏環粗上行枝的 NKCC2，效力最強；用於水腫、心衰竭；造成低血鉀、低血鎂。","c":"17.6"},
"thiazide":{"t":"噻嗪類利尿劑 thiazides","d":"抑制遠曲小管的 Na⁺–Cl⁻ 共同運輸，常用於高血壓；造成低血鉀、高尿酸，減少尿鈣。","c":"17.6"},
"ksparing":{"t":"保鉀利尿劑 potassium-sparing diuretics","d":"螺內酯（醛固酮拮抗劑）或 amiloride（阻斷 ENaC），作用在集尿管；效力弱，可能高血鉀。","c":"17.6"},
"mannitol":{"t":"甘露醇 mannitol","d":"能被過濾但不被再吸收的糖醇，提高小管液滲透壓而留住水分（滲透性利尿劑），用於降低腦壓。","c":"17.6"},
"aki":{"t":"急性腎損傷 acute kidney injury","d":"數小時到數天內腎功能快速下降，原因有腎血流不足、腎毒性藥物（NSAIDs、顯影劑）、尿路阻塞；常可恢復。","c":"17.6"},
"ckd":{"t":"慢性腎臟病 chronic kidney disease","d":"腎功能持續下降超過 3 個月，依 eGFR 分 1–5 期；主因糖尿病、高血壓；併發高血鉀、酸中毒、高磷、貧血、高血壓；飲食調整蛋白質、鈉、鉀、磷、水。","c":"17.6"},
"nephrotic":{"t":"腎病症候群 nephrotic syndrome","d":"過濾膜受損：大量蛋白尿（&gt; 3.5 g/天）、低白蛋白血症、水腫、高血脂。","c":"17.6"},
"uremia":{"t":"尿毒症 uremia","d":"末期腎病時含氮廢物等累積造成的全身症狀：噁心、食慾差、搔癢、疲倦、意識改變。","c":"17.6"},
"dialysis":{"t":"透析 dialysis","d":"<b>血液透析</b>：血液流過人工膜清除廢物與多餘水分（每週約 3 次）。<b>腹膜透析</b>：以腹膜為過濾膜。透析病人需增加蛋白質攝取並限制水、鉀、磷。","c":"17.6"},
"renalstone":{"t":"腎結石 renal stones","d":"最常見為草酸鈣結石；預防：多喝水、減鈉、適量動物蛋白，不需刻意限鈣；尿酸結石與高普林、尿液偏酸有關。","c":"17.6"}});
Object.assign(GL_ALIAS,{"腎元":"nephron","腎小體":"renalcorp","腎絲球":"glomerulus","鮑氏囊":"glomerulus","近曲小管":"pct","亨利氏環":"henle","遠曲小管":"dct","集尿管":"cd","近髓質腎元":"juxtamed","皮質腎元":"juxtamed","入球小動脈":"afferent","出球小動脈":"afferent","管周微血管":"peritubular","直血管":"peritubular","排尿反射":"micturition","排尿":"micturition","逼尿肌":"detrusor","外括約肌":"detrusor","內括約肌":"detrusor","足細胞":"podocyte","過濾膜":"filtmembrane","腎絲球過濾率":"gfr","GFR":"gfr","淨過濾壓":"netfilt","腎小管腎絲球回饋":"tgf","緻密斑":"maculadensa","近腎絲球器":"maculadensa","蛋白尿":"proteinuria","UACR":"proteinuria","逆流倍增":"countercurrent","逆流交換":"ccexchange","NKCC2":"nkcc2","水通道蛋白-2":"aqp2","必然性再吸收":"obligatory","兼性":"obligatory","清除率":"clearance","菊糖":"inulin","肌酸酐":"creatinine","血清肌酸酐":"creatinine","eGFR":"egfr","BUN":"bun","血中尿素氮":"bun","PAH":"pah","Tm":"tm","腎閾值":"tm","最大運輸量":"tm","糖尿":"glycosuria","SGLT2 抑制劑":"sglt2i","ENaC":"enac","上皮鈉通道":"enac","主細胞":"principal","間插細胞":"principal","高血鉀":"hyperkalemia","低血鉀":"hyperkalemia","NH₄⁺":"ammonia","可滴定酸":"titratable","環利尿劑":"loopdiuretic","噻嗪類":"thiazide","保鉀利尿劑":"ksparing","螺內酯":"ksparing","甘露醇":"mannitol","急性腎損傷":"aki","慢性腎臟病":"ckd","CKD":"ckd","腎病症候群":"nephrotic","尿毒症":"uremia","透析":"dialysis","血液透析":"dialysis","腹膜透析":"dialysis","腎結石":"renalstone"});

/* ---- end ch17 ---- */
/* ---- ch19 ---- */
Object.assign(GL,{"metrate":{"t":"代謝率 metabolic rate","d":"單位時間的能量消耗，可由耗氧量估算（每公升 O₂ 約 4.8 大卡）。","c":"19.1"},
"tee":{"t":"每日總能量消耗 total energy expenditure","d":"＝基礎代謝率（約 60–70%）＋攝食產熱效應（約 10%）＋身體活動（約 15–30%，最大變數）。","c":"19.1"},
"tef":{"t":"攝食產熱效應 thermic effect of food","d":"進食後消化、吸收、處理營養素增加的能量消耗，約占總消耗 10%；蛋白質 20–30% ＞ 醣類 5–10% ＞ 脂肪 0–3%。國考考過。","c":"19.1"},
"anabolism":{"t":"合成代謝、分解代謝","d":"<b>合成代謝</b>：小分子合成大分子，耗能，吸收期為主。<b>分解代謝</b>：大分子分解釋能，吸收後期為主。","c":"19.1"},
"essentialnut":{"t":"必需營養素 essential nutrients","d":"身體無法合成或合成不足、必須從食物攝取者：9 種必需胺基酸、必需脂肪酸（亞麻油酸、α-次亞麻油酸）、維生素、礦物質、水。","c":"19.1"},
"freeradical":{"t":"自由基、活性氧 free radicals / ROS","d":"帶未配對電子、活性很高的分子（超氧陰離子、羥基自由基等），主要來自粒線體；過多造成氧化壓力，傷害脂質、蛋白質、DNA。","c":"19.1"},
"antioxidant":{"t":"抗氧化防禦 antioxidants","d":"酵素：超氧化物歧化酶（Cu、Zn、Mn）、觸酶、麩胱甘肽過氧化酶（硒）；營養素：維生素 C、E、類胡蘿蔔素。","c":"19.1"},
"counterreg":{"t":"反調節激素 counterregulatory hormones","d":"對抗胰島素、升高血糖的激素：升糖素、腎上腺素、皮質醇、生長激素；降血糖則幾乎只靠胰島素。","c":"19.2"},
"arcuate":{"t":"弓狀核 arcuate nucleus","d":"下視丘調節食慾的關鍵區：NPY/AgRP 神經元刺激食慾，POMC（α-MSH）神經元抑制食慾；接收瘦體素、胰島素、飢餓素訊號。","c":"19.2"},
"pomc":{"t":"POMC、α-MSH","d":"POMC（前鴉片黑色素皮質素）切出的 α-MSH 作用於 MC4 受體，抑制食慾、增加能量消耗；MC4R 突變是常見的單基因肥胖原因。","c":"19.2"},
"adiponectin":{"t":"脂聯素 adiponectin","d":"脂肪細胞分泌、增加胰島素敏感性並抗發炎的激素；肥胖（特別是內臟脂肪多）時反而減少。","c":"19.2"},
"visceralfat":{"t":"內臟脂肪 visceral fat","d":"腹腔內臟周圍的脂肪，比皮下脂肪更易釋放脂肪酸與發炎物質，與胰島素阻抗、代謝症候群關係密切；以腰圍評估。","c":"19.2、19.4"},
"ucp1":{"t":"解偶聯蛋白 UCP1","d":"棕色脂肪粒線體內膜的蛋白，讓質子不經 ATP 合成酶回流，能量以熱釋放（非顫抖性產熱）。","c":"19.2"},
"thermoreg":{"t":"體溫調節 thermoregulation","d":"下視丘為中樞：冷時皮膚血管收縮、顫抖、非顫抖性產熱；熱時血管擴張、流汗。","c":"19.2"},
"shivering":{"t":"顫抖、非顫抖性產熱","d":"<b>顫抖</b>：骨骼肌不自主快速收縮產熱。<b>非顫抖性產熱</b>：棕色脂肪、交感神經與甲狀腺素提高代謝產熱。","c":"19.2"},
"betacell":{"t":"β 細胞的胰島素分泌","d":"葡萄糖經 GLUT2 進入 → 葡萄糖激酶 → ATP↑ → K_ATP 通道關閉 → 去極化 → Ca²⁺ 流入 → 胰島素胞吐。","c":"19.3"},
"katp":{"t":"ATP 敏感性 K⁺ 通道 K_ATP","d":"β 細胞膜上的 K⁺ 通道，ATP 增加時關閉引起去極化與胰島素分泌；磺醯尿素類藥物直接關閉它。","c":"19.3"},
"sulfonylurea":{"t":"磺醯尿素類 sulfonylureas","d":"關閉 β 細胞 K_ATP 通道、促進胰島素分泌的口服降血糖藥；主要副作用為低血糖與體重增加。","c":"19.3"},
"insulinact":{"t":"胰島素的作用","d":"GLUT4 上膜（肌肉、脂肪）；肝醣、脂肪、蛋白質合成↑；肝醣分解、糖質新生、脂解↓；K⁺ 進入細胞 → 降血糖、儲存能量。","c":"19.3"},
"glucagonact":{"t":"升糖素的作用","d":"主要作用於肝臟（cAMP）：肝醣分解、糖質新生、脂肪酸氧化與酮體生成↑ → 升血糖；對肌肉肝醣無作用。","c":"19.3"},
"glycogenolysis":{"t":"肝醣分解、肝醣合成","d":"<b>肝醣分解</b>：肝醣 → 葡萄糖（升糖素、腎上腺素促進）。<b>肝醣合成</b>：葡萄糖 → 肝醣（胰島素促進）。","c":"19.3"},
"absorptive":{"t":"吸收期、吸收後期","d":"<b>吸收期</b>（飯後）：胰島素高，葡萄糖為燃料，儲存肝醣與脂肪。<b>吸收後期</b>（空腹）：升糖素高，肝醣分解與糖質新生維持血糖，多數組織改用脂肪酸。","c":"19.3"},
"dm2":{"t":"糖尿病 diabetes mellitus","d":"慢性高血糖：空腹 ≥ 126、OGTT 2 小時 ≥ 200、HbA1c ≥ 6.5%（mg/dL）。第 1 型：自體免疫、胰島素缺乏；第 2 型（90%+）：胰島素阻抗。","c":"19.4；第 11 章"},
"hba1c":{"t":"糖化血色素 HbA1c","d":"血紅素被葡萄糖糖化的比例，反映約 2–3 個月的平均血糖；≥ 6.5% 可診斷糖尿病，5.7–6.4% 為前期；貧血與地中海型貧血會影響準確性。","c":"19.4"},
"ogtt":{"t":"口服葡萄糖耐受試驗 OGTT","d":"空腹喝下 75 g 葡萄糖，2 小時血糖 ≥ 200 mg/dL 為糖尿病、140–199 為葡萄糖耐受不良。","c":"19.4"},
"metsyn":{"t":"代謝症候群 metabolic syndrome","d":"台灣標準五項中三項以上：腰圍男 ≥ 90、女 ≥ 80 cm；血壓 ≥ 130/85；空腹血糖 ≥ 100；三酸甘油酯 ≥ 150；HDL 男 &lt; 40、女 &lt; 50 mg/dL。","c":"19.4"},
"ages":{"t":"糖化終產物 AGEs","d":"長期高血糖使蛋白質非酵素性糖化的產物，損傷血管與組織，是糖尿病併發症的機制之一。","c":"19.4"},
"dmcomp":{"t":"糖尿病慢性併發症","d":"小血管：視網膜病變、腎病變、神經病變（糖尿病足）。大血管：冠心病、中風、周邊動脈疾病。","c":"19.4"},
"hypoglycemia":{"t":"低血糖 hypoglycemia","d":"血糖 &lt; 70 mg/dL：交感症狀（心悸、手抖、冷汗、飢餓）與腦缺糖（混亂、抽搐、昏迷）；多因藥物過量、延誤進食、飲酒；15-15 法則處理。","c":"19.4"},
"insulinindep":{"t":"不需胰島素攝取葡萄糖的組織","d":"腦（GLUT1、GLUT3）、紅血球（GLUT1）、肝臟（GLUT2）、腎、小腸、β 細胞等；低血糖時仍能攝取。肌肉與脂肪需胰島素（GLUT4）。國考考過。","c":"19.4"},
"glut13":{"t":"GLUT1、GLUT3","d":"不依賴胰島素的葡萄糖運輸蛋白，對葡萄糖親和力高：GLUT1（紅血球、血腦障壁）、GLUT3（神經元），確保低血糖時腦仍能取得葡萄糖。","c":"19.4"},
"thyroxmeta":{"t":"甲狀腺激素的代謝作用","d":"提高 BMR 與產熱（Na⁺/K⁺ 幫浦、粒線體、解偶聯）；增加 β 受體（允許作用）；增加 LDL 受體；節食時 T₃ 下降以節省能量。","c":"19.5"},
"ghmeta":{"t":"生長激素的代謝作用","d":"經 IGF-1 促進生長與蛋白質合成；直接促進脂解、減少肌肉用糖、增加肝臟輸出葡萄糖（反胰島素作用）。","c":"19.5"},
"cortmeta":{"t":"皮質醇的代謝作用","d":"肌肉蛋白分解、肝臟糖質新生、脂解、減少周邊用糖（反胰島素）、允許升糖素與腎上腺素作用；長期過多 → 高血糖、肌肉流失、中央肥胖、骨質疏鬆。","c":"19.5"},
"bonerem":{"t":"骨重塑 bone remodeling","d":"造骨細胞沉積新骨、蝕骨細胞吸收舊骨，不斷進行（成人每年約 10%）；RANKL 活化蝕骨細胞、骨保護素抑制；骨峰約 30 歲。","c":"19.6"},
"rankl":{"t":"RANKL、骨保護素","d":"造骨細胞表現的 RANKL 結合蝕骨前驅細胞的 RANK 使其活化；骨保護素（OPG）是誘餌受體，阻止此作用。抗 RANKL 單株抗體用於治療骨質疏鬆。","c":"19.6"},
"serumca":{"t":"血鈣 plasma calcium","d":"正常約 8.5–10.5 mg/dL，約一半為游離鈣；參與神經、肌肉、凝血、分泌；過低使神經易興奮 → 手足抽搐。","c":"19.6"},
"tetany":{"t":"手足抽搐 tetany","d":"低血鈣使神經與肌肉膜易興奮而引起的不自主肌肉痙攣，常見於手足。","c":"19.6"},
"vitdact":{"t":"維生素 D 的活化","d":"皮膚（UVB，7-去氫膽固醇）或飲食 → 肝臟 25-羥化（25-(OH)D，評估營養狀況）→ 腎臟 1α-羥化（PTH、低磷促進）→ 1,25-(OH)₂D₃，增加腸道鈣磷吸收。","c":"19.6；第 11 章"},
"fgf23":{"t":"FGF23","d":"骨細胞分泌的激素，使腎臟排磷並抑制維生素 D 活化；慢性腎臟病時大量增加。","c":"19.6"},
"osteoporosis":{"t":"骨質疏鬆症 osteoporosis","d":"骨吸收大於形成、骨量減少與結構變差而易骨折；DXA 的 T 值 ≤ −2.5；危險因子停經、老化、低鈣與維生素 D、缺乏運動、類固醇。","c":"19.6"},
"rickets":{"t":"佝僂病、骨質軟化症","d":"維生素 D（或鈣、磷）不足使骨骼礦化不良：兒童為<b>佝僂病</b>（骨骼變形、O 型腿），成人為<b>骨質軟化症</b>。","c":"19.6"},
"bisphos":{"t":"雙磷酸鹽類 bisphosphonates","d":"附著在骨表面、抑制蝕骨細胞的骨質疏鬆藥物；口服需空腹以大量水服用並保持直立。","c":"19.6"}});
Object.assign(GL_ALIAS,{"代謝率":"metrate","每日總能量消耗":"tee","攝食產熱效應":"tef","攝食產熱":"tef","合成代謝":"anabolism","分解代謝":"anabolism","必需營養素":"essentialnut","輔酶":"coenzyme","自由基":"freeradical","活性氧":"freeradical","氧化壓力":"freeradical","超氧化物歧化酶":"antioxidant","麩胱甘肽過氧化酶":"antioxidant","反調節激素":"counterreg","弓狀核":"arcuate","POMC":"pomc","α-MSH":"pomc","脂聯素":"adiponectin","內臟脂肪":"visceralfat","UCP1":"ucp1","解偶聯蛋白":"ucp1","體溫調節":"thermoreg","顫抖":"shivering","非顫抖性產熱":"shivering","K_ATP":"katp","磺醯尿素":"sulfonylurea","肝醣分解":"glycogenolysis","肝醣合成":"glycogenolysis","脂解":"lipolysis","荷爾蒙敏感性脂酶":"hsl","吸收期":"absorptive","吸收後期":"absorptive","糖尿病":"dm2","糖化血色素":"hba1c","HbA1c":"hba1c","口服葡萄糖耐受試驗":"ogtt","OGTT":"ogtt","代謝症候群":"metsyn","糖化終產物":"ages","低血糖":"hypoglycemia","GLUT1":"glut13","GLUT3":"glut13","骨重塑":"bonerem","RANKL":"rankl","骨保護素":"rankl","血鈣":"serumca","手足抽搐":"tetany","FGF23":"fgf23","骨質疏鬆症":"osteoporosis","骨質疏鬆":"osteoporosis","佝僂病":"rickets","骨質軟化症":"rickets","雙磷酸鹽":"bisphos"});

/* ---- end ch19 ---- */
/* ---- ch11 ---- */
Object.assign(GL,{"hormclass":{"t":"激素的化學分類","d":"激素依化學結構分成幾大類，結構決定它溶不溶於水、怎麼運送、受體在哪裡。","c":"11.1","f":"<b>胺類</b>（由胺基酸衍生）：兒茶酚胺、褪黑激素、甲狀腺激素。<b>胜肽與蛋白質</b>：胰島素、GH、ADH、PTH。<b>醣蛋白</b>：FSH、LH、TSH、hCG。<b>類固醇</b>（由膽固醇衍生）：皮質醇、醛固酮、性激素、活性維生素 D。<br>水溶性激素（胜肽、兒茶酚胺）作用在細胞膜受體；脂溶性激素（類固醇、甲狀腺激素）進入細胞作用在核內受體。","m":"<b>水溶按門鈴、脂溶進屋改基因</b>；甲狀腺激素是胺類卻像類固醇。"},
"prohorm":{"t":"激素原、前激素 prohormone / prehormone","d":"激素原是「還沒剪好」的大分子，切開才成為激素；前激素是分泌出去後在別處被轉換成更有活性形式的激素。","c":"11.1","f":"激素原例：胰島素原 → 胰島素＋C 胜肽；POMC → ACTH、MSH、β-腦內啡。前激素例：T₄ → T₃（組織中脫碘）；睪固酮 → 雙氫睪固酮或雌二醇；維生素 D → 骨化三醇。","m":"<b>激素原在細胞內剪、前激素在細胞外轉</b>。"},
"synerg":{"t":"協同、允許、拮抗作用","d":"多個激素同時作用時，效果可能相加放大、互相幫忙，或互相抵消。","c":"11.1","f":"<b>協同</b>：腎上腺素＋升糖素一起升血糖，效果大於單獨相加。<b>允許</b>：甲狀腺激素增加 β 受體，讓腎上腺素在脂肪組織更有效。<b>拮抗</b>：胰島素降血糖 vs 升糖素升血糖。","m":"<b>加乘、鋪路、對抗</b>。"},
"permissive":{"t":"允許作用 permissive effect","d":"某激素本身不直接產生效果，但讓組織對另一激素反應更好，常是增加受體數量。","e":"甲狀腺激素增加 β 受體，允許腎上腺素促進脂肪分解。","c":"11.1","f":"例：皮質醇讓血管對兒茶酚胺有反應（缺皮質醇時血壓難以維持）；甲狀腺激素增加脂肪細胞的 β 受體，讓腎上腺素能有效分解脂肪；雌激素使子宮產生黃體素受體。","m":"<b>先幫你開門，別人才進得來</b>。"},
"updown":{"t":"上調、下調 up-regulation / down-regulation","d":"<b>上調</b>：受體增加、反應變敏感。<b>下調（脫敏）</b>：長期高濃度使受體減少、反應變差。","e":"第 2 型糖尿病長期高胰島素可使受體與訊號下降；GnRH 必須以脈衝方式分泌，持續給予反而下調受體（被用來治療攝護腺癌）。","c":"11.1","f":"受體數量會隨激素濃度調整：長期高濃度 → 受體減少或失去反應（下調、脫敏）；部分激素會增加自己或其他激素的受體（上調）。","m":"<b>太吵就關小聲（下調）</b>。"},
"hre":{"t":"激素反應元 hormone-response element","d":"DNA 上的一小段「門牌號碼」，讓激素–受體複合物知道要去開關哪些基因。","c":"11.2","f":"類固醇、甲狀腺激素、活性維生素 D、維生素 A 酸與核內受體結合後，受體的鋅指結構辨認 DNA 上的激素反應元 → 增加或減少該基因的轉錄。","m":"<b>受體拿著激素，去找 DNA 上的門牌</b>。"},
"rxr":{"t":"視網醇 X 受體 RXR","d":"與甲狀腺激素受體、維生素 D 受體配對成異二聚體的核受體，其配體是維生素 A 的衍生物。","c":"11.2","f":"RXR 與甲狀腺激素受體（TR）、維生素 D 受體（VDR）、PPAR、視網酸受體（RAR）配對成異二聚體，一起結合激素反應元；它的配體是 9-順式視網酸。所以維生素 A 會影響甲狀腺激素、維生素 D 的作用。","m":"<b>RXR＝很多核受體的固定搭檔</b>。"},
"plc":{"t":"磷脂酶 C phospholipase C","d":"把細胞膜上的磷脂質切成兩個訊號分子（IP₃ 與 DAG）的酵素。","c":"11.2；第 6 章","f":"激素 → Gq 蛋白 → 活化磷脂酶 C → 切開 PIP₂ → IP₃（使內質網放鈣）＋DAG（活化蛋白質激酶 C）。","e":"ADH 的 V₁ 受體、α₁ 腎上腺素受體、GnRH、TRH 都用這條路徑。","m":"<b>PLC 一刀切出兩個傳訊者</b>。"},
"tyrk":{"t":"酪胺酸激酶受體 receptor tyrosine kinase","d":"本身具酵素活性的膜受體：激素結合後自身磷酸化，再磷酸化細胞內蛋白質。胰島素、生長因子的受體屬此類。","c":"11.2","f":"胰島素、IGF-1、多種生長因子的受體：激素結合 → 兩個受體靠攏、互相把酪胺酸磷酸化 → 招來細胞內蛋白（如 IRS）→ 啟動 PI3K–Akt（代謝作用、GLUT4 移位）與 MAPK（生長）路徑。","e":"許多標靶抗癌藥是酪胺酸激酶抑制劑（藥名常以 -tinib 結尾）。","m":"<b>受體自己就是激酶</b>。"},
"pituitary":{"t":"腦垂腺 pituitary gland","d":"掛在下視丘下方的「主腺體」：<b>前葉</b>（GH、TSH、ACTH、FSH、LH、PRL）、<b>後葉</b>（ADH、催產素）。","c":"11.3","w":"顱底蝶骨的蝶鞍凹陷中，以漏斗柄懸掛在下視丘下方，靠近視交叉。","f":"分泌多種激素調控其他內分泌腺，所以被稱為「主腺體」；但它本身受下視丘指揮。","e":"腦下垂體腫瘤壓迫視交叉 → 雙顳側偏盲。","m":"<b>前葉 6 種：GH、TSH、ACTH、FSH、LH、PRL</b>（口訣「生甲腎卵黃乳」）；<b>後葉 2 種：ADH、催產素</b>。"},
"antpit":{"t":"腦垂腺前葉、後葉","d":"腦垂腺分成前葉與後葉，來源與控制方式完全不同。","c":"11.3","f":"<b>前葉</b>（腺垂體）：來自口腔頂部的上皮，自己合成激素；由下視丘的釋放／抑制激素經<b>門脈血管</b>控制。<b>後葉</b>（神經垂體）：下視丘神經元的軸突末梢，ADH 與催產素在下視丘合成、沿軸突運到後葉儲存，<b>神經衝動</b>到達時釋放。","m":"<b>前葉聽血管的話、後葉聽神經的話</b>。"},
"gh":{"t":"生長激素 growth hormone（GH）","d":"腦垂腺前葉分泌：經肝臟產生 IGF-1 促進骨骼與組織生長；直接促進蛋白質合成、脂肪分解、升高血糖。深睡時分泌最多。","c":"11.3；第 19 章","f":"<b>促進生長</b>（主要經 IGF-1）：骨骼生長板、肌肉蛋白質合成。<b>代謝作用</b>（直接）：促進脂肪分解、減少葡萄糖利用（升血糖、抗胰島素）、保留蛋白質。夜間深睡時分泌最多；運動、空腹、低血糖、胺基酸促進分泌；高血糖、肥胖、體抑素抑制。","e":"睡眠充足對兒童長高很重要；嚴重營養不良時 GH 升高但 IGF-1 很低（肝臟對 GH 反應差），生長仍遲緩。","m":"<b>GH 長骨長肉、燒脂肪、升血糖</b>。"},
"tsh":{"t":"甲狀腺刺激素 TSH","d":"腦垂腺前葉分泌，促進甲狀腺激素合成與分泌及甲狀腺生長；受 TRH 促進、受甲狀腺激素負回饋抑制。","c":"11.3、11.5","f":"經 cAMP 促進甲狀腺的碘攝取、甲狀腺球蛋白碘化、T₄／T₃ 釋放，並使甲狀腺細胞肥大增生。T₄／T₃ 回頭抑制下視丘 TRH 與 TSH（負回饋）。","e":"<b>TSH 是篩檢甲狀腺功能最敏感的指標</b>：TSH 高 → 甲狀腺功能低下；TSH 低 → 亢進（原發性時）。","m":"<b>甲狀腺低 → TSH 高；甲狀腺高 → TSH 低</b>。"},
"acth":{"t":"促腎上腺皮質激素 ACTH","d":"腦垂腺前葉分泌，促進腎上腺皮質分泌皮質醇；受 CRH 促進、皮質醇負回饋抑制。","c":"11.3、11.4","f":"由 POMC 切割而來；促進腎上腺皮質（主要束狀帶）分泌皮質醇。清晨分泌最多（晝夜節律），壓力時大量增加。","e":"ACTH 過多時（庫欣病、愛迪生氏症）同時切出的 MSH 會使皮膚變黑。","m":"<b>CRH → ACTH → 皮質醇</b>。"},
"fsh":{"t":"濾泡刺激素 FSH","d":"腦垂腺前葉分泌的促性腺激素：女性促進濾泡發育與雌激素，男性促進精子生成。","c":"11.3；第 20 章","f":"女性：促進濾泡生長、顆粒細胞把雄性素轉成雌激素（芳香化酶）。男性：作用在塞爾托利細胞，支持精子生成、分泌抑制素。抑制素回頭抑制 FSH。","m":"<b>FSH 養濾泡、養精子</b>。"},
"prl":{"t":"泌乳素（催乳素）prolactin（PRL）","d":"腦垂腺前葉分泌，促進乳腺<b>製造乳汁</b>；受多巴胺（PIH）抑制。注意不是催產素。","c":"11.3；第 20 章","f":"懷孕後期與哺乳時使乳腺製造乳汁；嬰兒吸吮刺激分泌，並抑制 GnRH（哺乳期月經較晚恢復）。下視丘的<b>多巴胺</b>持續抑制它的分泌。","e":"抗精神病藥阻斷多巴胺 → 泌乳素升高 → 溢乳、月經不規則；泌乳素瘤是最常見的腦下垂體腫瘤。","m":"<b>泌乳素「製造」乳汁、催產素「擠出」乳汁</b>。"},
"gonadotropin":{"t":"促性腺激素 gonadotropins","d":"作用在性腺（卵巢、睪丸）的兩種腦垂腺前葉激素：FSH 與 LH。","c":"11.3；第 20 章","f":"受下視丘 GnRH 脈衝刺激；性激素與抑制素回饋調控。女性 LH 高峰引發排卵；男性 LH 刺激萊迪希細胞製造睪固酮。","e":"極低體脂、過度運動、嚴重節食 → GnRH 脈衝受抑制 → 月經停止。","m":"<b>FSH、LH 都是「促性腺」</b>。"},
"relhorm":{"t":"釋放激素、抑制激素 releasing / inhibiting hormones","d":"下視丘分泌、用來命令腦垂腺前葉「多分泌」或「少分泌」的激素。","c":"11.3","f":"促進：TRH、CRH、GnRH、GHRH。抑制：體抑素（抑制 GH、TSH）、多巴胺（抑制泌乳素）。","m":"<b>泌乳素是唯一主要受「抑制」控制的前葉激素</b>。"},
"trh":{"t":"TRH、CRH、GnRH、GHRH","d":"下視丘的四個主要釋放激素，各自命令前葉分泌對應的激素。","c":"11.3","f":"TRH → TSH（也會增加泌乳素）；CRH → ACTH；GnRH → FSH、LH（必須脈衝式分泌）；GHRH → GH。","m":"<b>T 對 T、C 對 A、Gn 對 F/L、GH 對 GH</b>。"},
"somatostatin":{"t":"生長抑素 somatostatin","d":"下視丘分泌時抑制 GH（與 TSH）；胰島 δ 細胞與腸道也分泌，局部抑制胰島素、升糖素與消化活動。","c":"11.3、11.6","f":"下視丘的體抑素經門脈抑制 GH 與 TSH；胰島 δ 細胞的體抑素局部抑制胰島素與升糖素；腸胃道的體抑素抑制胃酸與多種消化激素。","e":"類似物 octreotide 用於肢端肥大症與神經內分泌腫瘤。","m":"<b>體抑素＝全面煞車</b>。"},
"axis":{"t":"下視丘—腦垂腺—標的腺體軸 axis","d":"下視丘 → 腦垂腺 → 標的腺體三層接力的激素系統，像公司的總經理 → 經理 → 員工。","c":"11.3","f":"三大軸：下視丘–腦垂腺–甲狀腺（TRH→TSH→T₄/T₃）、–腎上腺（CRH→ACTH→皮質醇）、–性腺（GnRH→FSH/LH→性激素）。標的激素以<b>負回饋</b>抑制上面兩層。","e":"判斷疾病在哪一層：例如 T₄ 低而 TSH 高 → 甲狀腺本身的問題（原發性）；T₄ 低且 TSH 也低 → 腦垂腺或下視丘的問題。","m":"<b>底層太多 → 上層就少發命令</b>。"},
"igf":{"t":"類胰島素生長因子 IGF-1（體介素）","d":"肝臟受 GH 刺激產生，促進骨骼生長板軟骨細胞分裂與組織生長；營養不良時降低。","c":"11.3","w":"主要由<b>肝臟</b>在 GH 刺激下製造；骨骼、肌肉等組織也會局部產生。","f":"促進生長板軟骨細胞分裂、肌肉與各組織的蛋白質合成與生長；作用類似胰島素（可降血糖）。IGF-1 回頭抑制 GH 分泌。","e":"營養不良、蛋白質與熱量不足 → IGF-1 下降 → 生長遲緩；IGF-1 也被用來評估營養狀況與 GH 疾病。","n":"結構與胰島素相似，所以叫「類胰島素」生長因子。","m":"<b>GH 下命令、IGF-1 去施工</b>。"},
"acromegaly":{"t":"肢端肥大症、巨人症、侏儒症","d":"GH 過多：兒童 → <b>巨人症</b>；成人 → <b>肢端肥大症</b>（手腳下巴增厚）。兒童 GH 不足 → <b>侏儒症</b>。","c":"11.3","f":"GH 過多（多為腦垂腺腫瘤）：生長板閉合前 → 長得極高（巨人症）；閉合後 → 骨骼無法變長，只能變粗：手腳變大、下巴與眉骨突出、內臟肥大，並有高血糖。GH 或 IGF-1 不足 → 侏儒症（比例正常的矮小）。","m":"<b>板開長高、板閉長粗</b>。"},
"adcortex":{"t":"腎上腺皮質 adrenal cortex","d":"腎上腺外層，分泌類固醇：球狀帶（醛固酮）、束狀帶（皮質醇）、網狀帶（雄性素）——鹽、糖、性。","c":"11.4","w":"腎上腺的外層（內層是髓質），由外到內分三層。","f":"<b>球狀帶</b> → 醛固酮（鹽）；<b>束狀帶</b> → 皮質醇（糖）；<b>網狀帶</b> → 雄性素（性）。原料都是膽固醇。","m":"<b>由外而內：鹽、糖、性</b>（GFR：Glomerulosa、Fasciculata、Reticularis）。"},
"aldosterone":{"t":"醛固酮 aldosterone","d":"礦物皮質素：使腎臟再吸收 Na⁺、分泌 K⁺ 與 H⁺，增加血容積與血壓；受腎素—血管收縮素系統與高血鉀刺激。","c":"11.4；第 14、17 章","w":"腎上腺皮質<b>球狀帶</b>分泌；作用在腎臟遠曲小管與集尿管的主細胞。","f":"經核內受體增加 Na⁺ 通道（ENaC）與鈉鉀幫浦 → 保 Na⁺（水跟著）、排 K⁺ 與 H⁺ → 血量與血壓↑。主要刺激：血管收縮素 II、高血鉀；ACTH 只有短暫作用。","e":"醛固酮過多（原發性醛固酮症）→ 高血壓、低血鉀、代謝性鹼中毒；螺內酯阻斷它（保鉀利尿劑）。","m":"<b>醛固酮：留鈉、趕鉀、趕酸</b>。"},
"cortisol":{"t":"皮質醇 cortisol","d":"糖皮質素：促進糖質新生（升血糖）、分解蛋白質、抗發炎、抑制免疫、允許兒茶酚胺作用；受 ACTH 控制，清晨最高。","c":"11.4；第 19 章","w":"腎上腺皮質<b>束狀帶</b>分泌；清晨最高、深夜最低。","f":"①升血糖：促進肝臟糖質新生、減少肌肉與脂肪攝取葡萄糖。②分解肌肉蛋白質提供胺基酸、促進脂肪分解。③抗發炎、抑制免疫。④允許兒茶酚胺維持血壓。⑤長期過多使骨質流失（抑制造骨、減少鈣吸收）。","e":"長期使用類固醇藥物：高血糖、肌肉流失、骨質疏鬆、體重增加、易感染——飲食要注意醣類、鈣與維生素 D、蛋白質，並限鈉。","m":"<b>皮質醇＝長期壓力激素：升糖、拆肌肉、抗發炎</b>。"},
"mineralo":{"t":"礦物皮質素、糖皮質素 mineralocorticoid / glucocorticoid","d":"腎上腺皮質激素依主要作用分成兩類：管鹽的礦物皮質素、管糖的糖皮質素。","c":"11.4","f":"礦物皮質素（醛固酮）：腎臟保鈉排鉀。糖皮質素（皮質醇）：升血糖、抗發炎；高濃度時也能結合礦物皮質素受體（腎臟以酵素把皮質醇轉成較無活性的皮質酮來保護）。","e":"大量吃甘草會抑制這個保護酵素 → 皮質醇作用在礦物皮質素受體 → 高血壓、低血鉀。","m":"<b>礦物管鹽、糖皮管糖</b>。"},
"cushing":{"t":"庫欣氏症候群 Cushing's syndrome","d":"皮質醇過多：月亮臉、水牛肩、中央肥胖、高血糖、高血壓、肌肉無力、骨質疏鬆；最常見原因是長期服用類固醇。","c":"11.4","f":"原因：最常見是長期使用類固醇藥物；其次是腦垂腺 ACTH 腫瘤（庫欣病）、腎上腺腫瘤。皮質醇過多 → 脂肪重新分布到臉、頸背、腹部，四肢肌肉萎縮變細、皮膚變薄、紫紋、高血糖、高血壓、骨質疏鬆、易感染。","m":"<b>月亮臉、水牛肩、細四肢</b>。"},
"addison":{"t":"愛迪生氏症 Addison's disease","d":"腎上腺皮質功能不足：皮質醇與醛固酮都缺乏 → 低血糖、低血壓、低血鈉、高血鉀、疲倦；ACTH 升高使皮膚色素沉著。","c":"11.4","f":"多為自體免疫破壞腎上腺皮質：皮質醇缺乏 → 低血糖、疲倦、體重下降、無法應付壓力；醛固酮缺乏 → 低血鈉、高血鉀、脫水、低血壓；ACTH 代償性升高 → 皮膚與黏膜變黑。","e":"病人常渴望吃鹹的；壓力（感染、手術）時需要增加類固醇劑量，否則可能發生致命的腎上腺危象。","m":"<b>愛迪生：黑、瘦、低血壓、想吃鹽</b>。"},
"pheo":{"t":"嗜鉻細胞瘤 pheochromocytoma","d":"腎上腺髓質的腫瘤，分泌過多兒茶酚胺，造成陣發性高血壓、心悸、頭痛、冒汗。","c":"11.4","f":"嗜鉻細胞（髓質細胞）腫瘤持續或陣發性分泌大量腎上腺素與正腎上腺素。典型三症狀：頭痛、心悸、冒汗，加上陣發性高血壓；也可能有高血糖、體重下降。","e":"檢驗尿或血中的兒茶酚胺代謝物（metanephrine、VMA）；過去檢驗前要避免香蕉、香草、咖啡等。","n":"pheo-＝暗色、chromo-＝顏色：細胞用鉻鹽染色後變成暗褐色（所以叫嗜鉻）。","m":"<b>頭痛、心悸、冒汗＋陣發性高血壓</b>。"},
"gas":{"t":"一般適應症候群 general adaptation syndrome","d":"身體面對長期壓力時的三階段反應：先緊急動員、再勉強撐住、最後撐不下去。","c":"11.4","f":"<b>警覺期</b>：交感神經與腎上腺髓質（腎上腺素）快速反應。<b>抵抗期</b>：下視丘–腦垂腺–腎上腺軸，皮質醇長期維持血糖與血壓。<b>耗竭期</b>：資源耗盡、免疫力下降、容易生病。","n":"由匈牙利裔加拿大學者 Hans Selye 於 1936 年提出。","m":"<b>警覺 → 抵抗 → 耗竭</b>。"},
"thyroid":{"t":"甲狀腺 thyroid gland","d":"頸部氣管前方的蝴蝶形腺體，濾泡細胞分泌 T₄、T₃，濾泡旁細胞（C 細胞）分泌降鈣素。","c":"11.5","w":"頸部前方、喉結下方，包住氣管前面，左右兩葉以峽部相連。","f":"<b>濾泡細胞</b>：攝取碘，合成甲狀腺球蛋白，製造並分泌 T₄、T₃。<b>濾泡旁細胞（C 細胞）</b>：分泌降鈣素。","e":"甲狀腺是唯一把大量激素儲存在細胞外（濾泡膠體中）的內分泌腺，可存約數週的量。","m":"<b>濾泡做 T₄/T₃、C 細胞做降鈣素</b>。"},
"t4":{"t":"甲狀腺素 T₄、T₃","d":"<b>T₄</b>（4 個碘）占分泌的約 90%；<b>T₃</b>（3 個碘）活性較強，多由 T₄ 在組織中脫碘而來（脫碘酶含硒）。","c":"11.5","f":"兩者都由酪胺酸＋碘組成，在血中大多與蛋白質（甲狀腺素結合球蛋白）結合。進入細胞後，T₄ 由含<b>硒</b>的去碘酶轉成 T₃ → 與細胞核的甲狀腺激素受體（配對 RXR）結合 → 增加鈉鉀幫浦、粒線體、產熱與代謝相關基因 → 基礎代謝率上升；並促進腦部發育與生長。","e":"飢餓時身體減少 T₄ 轉成 T₃（低 T₃ 狀態），降低代謝以節省能量。","m":"<b>T₄ 量多、T₃ 力強</b>；轉換靠硒。"},
"thyroglob":{"t":"甲狀腺球蛋白 thyroglobulin","d":"甲狀腺濾泡裡的大型蛋白質，是製造甲狀腺激素的「骨架」與「倉庫」。","c":"11.5","f":"在濾泡細胞合成後分泌到濾泡腔；其上的酪胺酸被甲狀腺過氧化酶碘化，再兩兩偶合成 T₄、T₃。需要時濾泡細胞把它胞吞回來，用溶體酵素切下 T₄、T₃ 釋放到血中。","e":"甲狀腺癌切除後，血中甲狀腺球蛋白可用來追蹤是否復發。","m":"<b>甲狀腺球蛋白＝T₄ 的生產線兼倉庫</b>。"},
"bmr":{"t":"基礎代謝率 basal metabolic rate（BMR）","d":"清醒、安靜、空腹、舒適溫度下維持生命所需的能量消耗；甲狀腺激素是主要調節因子。","c":"11.5；第 19 章","f":"約占每日總熱量消耗的 60–70%。影響因素：瘦體組織（肌肉）量最重要、甲狀腺激素、性別（男性較高）、年齡（隨年齡下降）、體表面積、發燒（每升高 1°C 約增加 13%）、懷孕、生長期、長期節食（下降）。","e":"肌肉量多的人 BMR 較高；激烈節食使 BMR 降低，減重變慢。","m":"<b>BMR 最大決定因素：瘦體組織</b>。"},
"hypothyroid":{"t":"甲狀腺功能低下、亢進","d":"甲狀腺激素太少（低下）或太多（亢進），全身代謝就會變慢或變快。","c":"11.5","f":"<b>低下</b>：怕冷、疲倦、體重增加、便秘、心跳慢、皮膚乾、思考遲緩、黏液水腫；血膽固醇升高。<b>亢進</b>：怕熱、多汗、體重下降但食慾增加、心悸、手抖、腹瀉、焦慮、失眠；葛瑞夫茲病還會突眼。","e":"甲狀腺亢進病人需要增加熱量與蛋白質；甲狀腺素藥物要空腹服用，避免與鈣片、鐵劑、大豆製品同時吃。","m":"<b>低下：慢、冷、胖；亢進：快、熱、瘦</b>。"},
"goiter":{"t":"甲狀腺腫 goiter","d":"甲狀腺腫大。碘缺乏時 T₄ 不足、TSH 增加而長大（地方性甲狀腺腫）；葛瑞夫茲病由抗體刺激而長大。","c":"11.5","f":"任何使 TSH 長期升高或甲狀腺受刺激的原因都會造成甲狀腺腫：碘缺乏（T₄ 做不出來 → TSH↑）、葛瑞夫茲病（抗體刺激）、橋本氏甲狀腺炎、甲狀腺結節。","e":"加碘鹽大幅降低地方性甲狀腺腫；生的十字花科蔬菜、樹薯含致甲狀腺腫物質。","m":"<b>腫大不代表功能高，低下也會腫</b>。"},
"cretinism":{"t":"呆小症 cretinism","d":"嬰幼兒甲狀腺激素不足造成的生長遲緩與智能障礙；新生兒篩檢可早期發現治療。","c":"11.5","f":"胎兒與嬰兒期甲狀腺激素對腦部神經發育與骨骼生長不可或缺；缺乏且未及時治療 → 永久性智能障礙、身材矮小。原因：懷孕期嚴重缺碘（地方性）或先天甲狀腺功能低下。","e":"台灣新生兒篩檢包含先天性甲狀腺低能症，出生後早期補充甲狀腺素可正常發育；孕婦需要足夠的碘。","m":"<b>嬰兒缺甲狀腺素 → 呆小症</b>。"},
"graves":{"t":"葛瑞夫茲病 Graves' disease","d":"自體抗體模仿 TSH 持續刺激甲狀腺，造成甲狀腺亢進與腫大、突眼；TSH 本身反而很低。","c":"11.5","f":"自體抗體（TSI）與 TSH 受體結合並持續刺激 → T₄、T₃ 大量分泌 → 負回饋使 TSH 很低；抗體也作用在眼窩組織 → 突眼。","e":"治療：抗甲狀腺藥物、放射性碘、手術；放射性碘治療前要低碘飲食。","n":"以 19 世紀愛爾蘭醫師 Robert Graves 命名。","m":"<b>抗體冒充 TSH</b>：亢進＋甲狀腺腫＋突眼。"},
"hashimoto":{"t":"橋本氏甲狀腺炎 Hashimoto's thyroiditis","d":"自體免疫破壞甲狀腺，是甲狀腺功能低下最常見的原因（碘充足地區）。","c":"11.5","f":"自體免疫（抗甲狀腺過氧化酶抗體等）使淋巴球浸潤並破壞甲狀腺 → 激素減少 → TSH 升高 → 甲狀腺可能腫大，最後功能低下。女性較多。","e":"需終生服用甲狀腺素；過量補碘可能加重甲狀腺炎。","n":"1912 年日本醫師橋本策首先描述。","m":"<b>橋本：免疫破壞 → 低下</b>（葛瑞夫茲：免疫刺激 → 亢進）。"},
"pth":{"t":"副甲狀腺素 parathyroid hormone（PTH）","d":"血鈣下降時由副甲狀腺分泌：骨骼釋放鈣、腎臟保鈣排磷、活化維生素 D 使腸道吸收鈣 → 血鈣上升。","c":"11.5；第 19 章","w":"副甲狀腺：甲狀腺背面通常四顆米粒大小的腺體。","f":"血中游離鈣下降 → 鈣感受器 → PTH 分泌：①<b>骨骼</b>：間接活化蝕骨細胞釋鈣磷；②<b>腎臟</b>：遠曲小管再吸收鈣、近曲小管減少磷再吸收（排磷）、活化 1α-羥化酶製造骨化三醇；③骨化三醇使<b>腸道</b>吸收鈣。結果：血鈣↑、血磷↓。","e":"慢性腎臟病：磷排不掉、活性維生素 D 不足 → 血鈣低 → PTH 長期升高（次發性副甲狀腺亢進）→ 骨病變。","m":"<b>PTH：骨放鈣、腎留鈣排磷、活化 D</b>。"},
"calcitonin":{"t":"降鈣素 calcitonin","d":"甲狀腺濾泡旁細胞（C 細胞）在血鈣升高時分泌，抑制蝕骨細胞、降低血鈣；成人作用小。","c":"11.5","f":"血鈣升高時分泌，抑制蝕骨細胞、減少骨鈣釋放、增加腎臟排鈣 → 血鈣下降。人類成人中作用很小，切除甲狀腺後血鈣仍能維持。","e":"人工鮭魚降鈣素曾用於骨質疏鬆與高血鈣；甲狀腺髓質癌時血中降鈣素升高。","m":"<b>降鈣素：C 細胞做、把鈣「降」下來</b>。"},
"osteoclast":{"t":"蝕骨細胞、造骨細胞 osteoclast / osteoblast","d":"骨骼一直在「拆」和「蓋」：蝕骨細胞負責拆，造骨細胞負責蓋。","c":"11.5；第 19 章","f":"<b>蝕骨細胞</b>：多核巨細胞（單核球系），分泌酸與蛋白酶溶解骨基質、釋放鈣磷。<b>造骨細胞</b>：分泌膠原蛋白與骨基質，並使其礦化；被包埋後成為骨細胞。PTH 經造骨細胞產生 RANKL 間接活化蝕骨細胞。","e":"骨質疏鬆是拆多於蓋；雌激素抑制蝕骨細胞，所以停經後骨質流失加快；雙磷酸鹽類藥物抑制蝕骨細胞。","m":"<b>clast 拆、blast 蓋</b>。"},
"calcitriol":{"t":"活性維生素 D（骨化三醇）1,25-(OH)₂D₃","d":"維生素 D 在肝臟（25-羥化）與腎臟（1α-羥化，PTH 促進）兩次活化後的形式，促進腸道吸收鈣磷。","c":"11.5；第 19 章","f":"由 VDR（配對 RXR）作用：①小腸：增加鈣與磷的吸收（鈣通道、鈣結合蛋白）；②腎臟：增加鈣再吸收；③骨骼：與 PTH 協同動員骨鈣，也幫助礦化。腎臟的 1α-羥化酶受 PTH 與低血磷促進。","e":"慢性腎臟病無法製造骨化三醇，要直接補充活性型。","m":"<b>肝 25、腎 1 → 骨化三醇</b>。"},
"islets2":{"t":"胰島的細胞","d":"胰臟中一小團一小團的內分泌細胞，各自分泌調節血糖的激素。","c":"11.6","f":"<b>β 細胞</b>（最多，60–70%）：胰島素，降血糖。<b>α 細胞</b>（約 20%）：升糖素，升血糖。<b>δ 細胞</b>：體抑素，局部抑制 α、β。<b>PP 細胞</b>：胰多胜肽。","m":"<b>α 餓、β 飽、δ 壓</b>。"},
"dm":{"t":"第 1 型、第 2 型糖尿病","d":"血糖長期過高的疾病，主要分成「沒有胰島素」的第 1 型和「胰島素不夠用」的第 2 型。","c":"11.6；第 19 章","f":"<b>第 1 型</b>：自體免疫破壞 β 細胞 → 胰島素絕對缺乏 → 多發於年輕人、體型不胖、需終生注射胰島素、容易發生<b>酮酸中毒</b>。<b>第 2 型</b>：胰島素阻抗＋β 細胞功能逐漸下降 → 多與肥胖、缺乏運動、遺傳有關，占 90% 以上；嚴重高血糖時可能出現高血糖高滲透壓狀態。","e":"飲食重點：醣類定量並平均分配、選全穀高纖、少含糖飲料、控制體重；配合運動與藥物。","m":"<b>1 型沒有、2 型不夠用</b>；三多一少：吃多、喝多、尿多、體重減少。"},
"incretin":{"t":"腸泌素 incretins","d":"進食時腸道分泌、在血糖上升前就促進胰島素分泌的激素：GIP 與 GLP-1。GLP-1 類似物是新型降血糖與減重藥物。","c":"11.6；第 18、19 章","f":"GIP（十二指腸 K 細胞）與 GLP-1（迴腸與結腸 L 細胞）在食物進入腸道時分泌，經 cAMP 增強「葡萄糖引發」的胰島素分泌；GLP-1 還抑制升糖素、延緩胃排空、增加飽足感。被 DPP-4 很快分解。","e":"口服葡萄糖比靜脈注射同量葡萄糖引起更多胰島素分泌（腸泌素效應）；GLP-1 受體致效劑與 DPP-4 抑制劑是糖尿病與肥胖的藥物。","m":"<b>腸道先打電話給胰臟</b>。"},
"thymus":{"t":"胸腺 thymus","d":"胸骨後方的器官，T 淋巴球在此成熟；兒童期最大，青春期後逐漸萎縮成脂肪。","c":"11.6；第 15 章","w":"胸骨後方、心臟上方的縱膈腔中。","f":"未成熟的 T 淋巴球從骨髓移到胸腺，經過「正選擇」（能辨認自身 MHC）與「負選擇」（刪除會攻擊自己的細胞）後成熟；胸腺上皮也分泌胸腺素等激素。","e":"蛋白質–熱量營養不良會使胸腺萎縮、T 細胞免疫下降，所以營養不良的人容易感染。","m":"<b>T 細胞的 T＝Thymus 胸腺</b>。"},
"hcg":{"t":"人類絨毛膜促性腺激素 hCG","d":"胚胎與胎盤分泌，維持黃體繼續分泌黃體素；是驗孕試劑檢測的對象。","c":"11.6；第 20 章","f":"受精卵著床後由滋養層細胞分泌，結構和 LH 類似 → 維持黃體繼續分泌黃體素與雌激素，直到懷孕約 10 週胎盤能自己製造為止；也刺激男胎睪丸分泌睪固酮。","e":"驗孕試劑檢測尿中的 hCG；hCG 在懷孕初期快速上升，與孕吐高峰時間相近。","m":"<b>hCG＝救黃體的訊號</b>。"},
"hpl":{"t":"人類胎盤催乳素 hPL","d":"胎盤分泌，使母體產生胰島素阻抗，把葡萄糖留給胎兒；與妊娠糖尿病有關。","c":"11.6；第 20 章","w":"由胎盤（融合滋養層）分泌，懷孕後期逐漸增加。","f":"作用類似 GH 與泌乳素：使母體產生<b>胰島素阻抗</b>、增加脂肪分解 → 母親多用脂肪當燃料，把葡萄糖與胺基酸留給胎兒；也幫助乳腺發育。","e":"若母親 β 細胞無法代償增加的胰島素需求 → 妊娠糖尿病；孕期 24–28 週做葡萄糖耐受測試篩檢。","m":"<b>hPL 讓媽媽省糖給寶寶</b>。"},
"anp":{"t":"心房利鈉胜肽 ANP","d":"心房被血容積撐開時分泌，促進腎臟排鈉排水、擴張血管、降低血壓；作用與醛固酮相反。","c":"11.6；第 14 章","w":"心房的心肌細胞（血量增加使心房被撐開時分泌）。","f":"使腎臟排鈉排水（利鈉利尿）、擴張血管、抑制腎素與醛固酮分泌 → 降低血量與血壓。","e":"心衰竭時心室也會分泌類似的 BNP；血中 BNP 用來診斷與追蹤心衰竭。","m":"<b>ANP 與醛固酮唱反調</b>。"},
"epo":{"t":"紅血球生成素 erythropoietin（EPO）","d":"腎臟在缺氧時分泌，刺激骨髓製造紅血球；腎衰竭時不足造成貧血。","c":"11.6；第 13 章","w":"主要由<b>腎臟</b>皮質的間質細胞分泌（少量由肝臟）。","f":"腎臟偵測到組織缺氧（缺氧誘導因子 HIF）→ 分泌 EPO → 刺激骨髓的紅血球前驅細胞增生與分化 → 紅血球增加、攜氧能力回升。","e":"慢性腎臟病的貧血主要是 EPO 不足，治療用 EPO 製劑並補充足夠的鐵；高海拔居民 EPO 較高；運動員違法使用 EPO 增加耐力。","m":"<b>腎臟缺氧 → EPO → 骨髓造紅血球</b>。"},
"leptin":{"t":"瘦體素 leptin","d":"脂肪細胞分泌，告訴下視丘體脂存量，抑制食慾、增加能量消耗；肥胖者常有瘦體素阻抗。","n":"希臘文 leptos＝瘦。","c":"11.6；第 19 章","w":"<b>脂肪細胞</b>分泌，量與體脂肪多少成正比。","f":"經血液到下視丘弓狀核：抑制促進食慾的 NPY／AgRP 神經元、活化抑制食慾的 POMC 神經元 → 食慾下降、能量消耗增加；也影響生殖（體脂太低時瘦體素低 → 月經停止）。","e":"多數肥胖者瘦體素很高，但大腦反應變差（瘦體素阻抗），所以補充瘦體素無法治療一般肥胖；先天缺乏瘦體素的罕見病人補充後明顯變瘦。","m":"<b>脂肪多 → 瘦體素多 → 叫大腦少吃</b>。"},
"ghrelin":{"t":"飢餓素 ghrelin","d":"空腹時胃分泌，刺激下視丘增加食慾，也促進 GH 分泌；進食後下降。","c":"11.6；第 18、19 章","w":"主要由<b>胃底</b>的內分泌細胞分泌。","f":"空腹時上升、進食後下降：作用在下視丘弓狀核促進食慾（活化 NPY／AgRP），並刺激 GH 分泌。","e":"睡眠不足使飢餓素增加、瘦體素減少 → 食慾變大；胃繞道或袖狀胃切除後飢餓素下降，可能是減重效果的原因之一。","m":"<b>飢餓素＝胃在喊餓</b>（瘦體素＝脂肪說夠了）。"},
"growthf":{"t":"生長因子 growth factors","d":"以旁泌或自泌方式促進特定細胞分裂與生長的蛋白質，如 NGF、EGF、PDGF、IGF。","c":"11.7","f":"以旁泌、自泌方式作用，多經酪胺酸激酶受體促進細胞分裂、存活與分化。例：NGF（神經）、EGF（上皮）、PDGF（血小板釋放，促進傷口修復與平滑肌增生）、IGF、VEGF（血管新生）。","e":"許多癌症的生長因子或其受體過度活化；抗 VEGF 藥物用來治療某些癌症與黃斑部病變。","m":"<b>局部的「長大」命令</b>。"},
"cytokine":{"t":"細胞激素 cytokines","d":"免疫細胞等分泌的訊號蛋白（如介白素），調節免疫與發炎反應。","c":"11.7；第 15 章","f":"由白血球、內皮細胞、脂肪細胞等分泌的小蛋白：介白素（IL）、干擾素、腫瘤壞死因子（TNF-α）、趨化素等；調控免疫細胞增生、發炎、發燒與急性期反應。","e":"嚴重感染、燒燙傷、癌症時大量的 IL-1、IL-6、TNF-α → 食慾下降、肌肉分解、發燒（惡病質）；肥胖的脂肪組織也分泌發炎性細胞激素，與胰島素阻抗有關。","m":"<b>細胞激素＝免疫系統的簡訊</b>。"},
"endothelin":{"t":"內皮素 endothelin","d":"血管內皮細胞分泌的強力血管收縮物質，與一氧化氮共同調節局部血流。","c":"11.7；第 14 章","f":"由血管內皮細胞製造，作用在血管平滑肌使其強力且持久地收縮；與一氧化氮（擴張）互相制衡，調節局部血流與血壓。","e":"肺動脈高壓的治療藥物之一是內皮素受體拮抗劑。","m":"<b>內皮素收縮 vs 一氧化氮擴張</b>。"},
"cox":{"t":"環氧化酶 cyclooxygenase（COX）","d":"把花生四烯酸轉成前列腺素與血栓素的酵素。COX-1 常態存在，COX-2 在發炎時被誘導；阿斯匹靈等 NSAIDs 抑制它。","c":"11.7","f":"花生四烯酸 →（COX）→ PGH₂ → 依組織不同轉成各種前列腺素、前列環素（內皮）、血栓素（血小板）。<b>COX-1</b>：常態存在，保護胃黏膜、維持腎血流、血小板凝集。<b>COX-2</b>：發炎時被誘導產生。","e":"阿斯匹靈與一般 NSAIDs 同時抑制 COX-1 與 COX-2，所以會傷胃；選擇性 COX-2 抑制劑較不傷胃，但可能增加心血管風險。","m":"<b>COX-1 顧家（胃、腎、血小板）、COX-2 管發炎</b>。"},
"thromboxane":{"t":"血栓素 thromboxane A₂","d":"血小板以 COX 製造的類二十碳酸，促進血小板凝集與血管收縮；低劑量阿斯匹靈抑制它。","c":"11.7；第 13 章","w":"由<b>血小板</b>經 COX-1 製造。","f":"促進血小板活化與凝集、血管收縮，有利於止血。","e":"低劑量阿斯匹靈<b>不可逆</b>地抑制血小板的 COX-1；血小板沒有細胞核無法再製造酵素，所以作用維持約 7–10 天（血小板的壽命），用來預防心肌梗塞與中風。EPA 產生的血栓素 A₃ 作用較弱。","m":"<b>血栓素「促」凝、前列環素「抗」凝</b>。"},
"prostacyclin":{"t":"前列環素 prostacyclin","d":"血管內皮製造的類二十碳酸，抑制血小板凝集、擴張血管，與血栓素作用相反。","c":"11.7","w":"由<b>血管內皮細胞</b>製造。","f":"經 cAMP 抑制血小板凝集、使血管擴張，防止正常血管內形成血栓；與血小板的血栓素互相平衡。","e":"內皮受損（動脈硬化）時前列環素減少，血小板較容易凝集。","m":"<b>內皮做前列環素、血小板做血栓素</b>。"},
"leukotriene":{"t":"白三烯素 leukotrienes","d":"花生四烯酸經脂氧化酶產生，引起支氣管收縮與發炎，與氣喘、過敏有關。","c":"11.7","f":"由白血球與肥大細胞的 5-脂氧化酶製造：使支氣管平滑肌強力收縮、血管通透性增加、吸引白血球，是氣喘與過敏的重要介質。","e":"白三烯素受體拮抗劑（如 montelukast）用來治療氣喘與過敏性鼻炎；阿斯匹靈抑制 COX 可能使更多花生四烯酸轉向白三烯素，引發「阿斯匹靈型氣喘」。","n":"最早在白血球（leuko-）中發現，結構含三個共軛雙鍵（-triene）。","m":"<b>COX → 前列腺素；LOX → 白三烯素</b>。"},
"nsaid":{"t":"非類固醇抗發炎藥 NSAIDs","d":"抑制 COX 的藥物（阿斯匹靈、布洛芬等）：止痛、退燒、消炎；副作用為胃潰瘍、出血、腎功能影響。","c":"11.7","f":"抑制 COX → 前列腺素減少 → 止痛、退燒、消炎；同時減少保護胃黏膜的前列腺素與腎臟血流。","e":"副作用：胃潰瘍與出血、腎功能下降（特別是脫水或已有腎病時）、血壓升高。慢性腎臟病人應避免長期使用。","m":"<b>NSAIDs 傷胃、傷腎</b>。"},
"eicos":{"t":"類二十碳酸 eicosanoids","d":"由 20 碳脂肪酸（花生四烯酸、EPA）衍生的局部訊號分子：前列腺素、血栓素、前列環素、白三烯素。","c":"11.7；第 2 章","f":"細胞受刺激時磷脂酶 A₂ 從膜上切下 20 碳脂肪酸 → 經 COX 產生前列腺素、前列環素、血栓素；經脂氧化酶產生白三烯素。作用在附近細胞，半衰期很短。","e":"ω-6 的花生四烯酸產生的發炎與凝血作用較強；ω-3 的 EPA 產生的較弱——這是魚油抗發炎、抗凝血的基礎。","n":"希臘文 <i>eicosa</i>＝二十。","m":"<b>20 碳 → 局部訊號</b>：PG、PGI、TX、LT。"},
"diins":{"t":"尿崩症 diabetes insipidus","d":"ADH 缺乏（或腎臟對 ADH 無反應），腎臟無法回收水，排出大量稀尿、口渴。與糖尿病無關。","n":"diabetes＝通過（多尿）、insipidus＝無味的（尿沒有甜味）；mellitus＝甜的。","c":"11.3；第 17 章","f":"<b>中樞性</b>：下視丘或後葉受損，ADH 分泌不足 → 補充 ADH 類似物（desmopressin）。<b>腎因性</b>：腎臟對 ADH 沒反應（遺傳、鋰鹽、低血鉀、高血鈣）。兩者都排大量稀尿（每天可達數公升）、尿比重低、極度口渴。","e":"與糖尿病（diabetes mellitus）不同：尿崩症的尿不含糖。病人要能自由喝水，避免脫水與高血鈉。","m":"<b>尿崩＝沒有 ADH、尿多而淡、不甜</b>。"},
"hypoportal":{"t":"下視丘—垂體門脈系統 hypothalamo-hypophyseal portal system","d":"連接下視丘與腦垂腺前葉的兩套微血管，讓下視丘激素不經全身循環、直接送到前葉。","c":"11.3","w":"下視丘底部的第一套微血管 → 沿漏斗柄下行的門脈靜脈 → 腦垂腺前葉的第二套微血管。","f":"下視丘釋放激素與抑制激素直接送到前葉，濃度很高、不會被全身血液稀釋，作用快速精準。","m":"<b>兩套微血管中間夾一段靜脈＝門脈</b>（肝門靜脈也是這種結構）。"}});
Object.assign(GL_ALIAS,{"激素原":"prohorm","前激素":"prohorm","協同":"synerg","允許作用":"permissive","上調":"updown","下調":"updown","脫敏":"updown","激素反應元":"hre","視網醇 X 受體":"rxr","RXR":"rxr","磷脂酶 C":"plc","酪胺酸激酶":"tyrk","前葉":"antpit","後葉":"antpit","生長激素":"gh","GH":"gh","甲狀腺刺激素":"tsh","TSH":"tsh","促腎上腺皮質激素":"acth","ACTH":"acth","濾泡刺激素":"fsh","FSH":"fsh","泌乳素":"prl","催乳素":"prl","PRL":"prl","促性腺激素":"gonadotropin","尿崩症":"diins","門脈系統":"hypoportal","釋放激素":"relhorm","抑制激素":"relhorm","TRH":"trh","CRH":"trh","GnRH":"trh","GHRH":"trh","生長抑素":"somatostatin","IGF-1":"igf","類胰島素生長因子":"igf","體介素":"igf","肢端肥大症":"acromegaly","巨人症":"acromegaly","侏儒症":"acromegaly","腎上腺皮質":"adcortex","醛固酮":"aldosterone","皮質醇":"cortisol","礦物皮質素":"mineralo","糖皮質素":"mineralo","庫欣氏症候群":"cushing","庫欣":"cushing","愛迪生氏症":"addison","愛迪生":"addison","嗜鉻細胞瘤":"pheo","一般適應症候群":"gas","甲狀腺":"thyroid","T₄":"t4","T₃":"t4","甲狀腺球蛋白":"thyroglob","基礎代謝率":"bmr","BMR":"bmr","甲狀腺功能低下":"hypothyroid","甲狀腺功能亢進":"hypothyroid","甲狀腺腫":"goiter","呆小症":"cretinism","葛瑞夫茲病":"graves","橋本氏甲狀腺炎":"hashimoto","副甲狀腺素":"pth","PTH":"pth","降鈣素":"calcitonin","蝕骨細胞":"osteoclast","造骨細胞":"osteoclast","1,25-(OH)₂D₃":"calcitriol","骨化三醇":"calcitriol","第 1 型糖尿病":"dm","第 2 型糖尿病":"dm","腸泌素":"incretin","GLP-1":"incretin","GIP":"incretin","胸腺":"thymus","hCG":"hcg","hPL":"hpl","心房利鈉胜肽":"anp","ANP":"anp","紅血球生成素":"epo","EPO":"epo","瘦體素":"leptin","飢餓素":"ghrelin","生長因子":"growthf","細胞激素":"cytokine","內皮素":"endothelin","環氧化酶":"cox","COX":"cox","血栓素":"thromboxane","前列環素":"prostacyclin","白三烯素":"leukotriene","NSAIDs":"nsaid","類二十碳酸":"eicos"});

